  const showToast = (message, type = 'info') => {
    const id = 'heilog-toast';
    let container = document.getElementById(id);
    if (!container) {
      container = document.createElement('div');
      container.id = id;
      container.className = 'fixed bottom-4 right-4 z-[9999] space-y-2';
      document.body.appendChild(container);
    }
    const el = document.createElement('div');
    const base = 'px-4 py-3 rounded-lg shadow-lg border text-sm max-w-sm';
    const styles = {
      info: 'bg-gray-800 border-gray-600 text-gray-100',
      success: 'bg-green-900/70 border-green-600 text-green-100',
      error: 'bg-red-900/70 border-red-600 text-red-100'
    };
    el.className = `${base} ${styles[type] || styles.info}`;
    el.textContent = message;

    container.appendChild(el);

    setTimeout(() => {
      el.style.opacity = '0';
      el.style.transition = 'opacity 0.3s';
    }, 2600);

    setTimeout(() => {
      el.remove();
      if (!container.children.length) container.remove();
    }, 3100);
  };

  const debounce = (fn, delay = 150, maxWait = 0) => {
    let timer, deadline, latest;
    const flush = () => { clearTimeout(timer); clearTimeout(deadline); timer=deadline=null; fn(...latest); };
    return (...args) => {
      latest=args;clearTimeout(timer);timer=setTimeout(flush,delay);
      if(maxWait && !deadline)deadline=setTimeout(flush,maxWait);
    };
  };

  const escapeHtml = (input = '') => {
    const str = String(input ?? '');
    return str.replace(/[&<>"'`=\/]/g, (s) => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;',
      '`': '&#x60;',
      '=': '&#x3D;',
      '/': '&#x2F;'
    }[s]));
  };



