 return `<div class="ewm-flow other-operation"><div class="ewm-flow-heading"><strong>${escapeHtml(getOtherOperationType(op))}</strong><span>Atendimento de outras operações</span></div><div class="other-status-track">${['Aguardando','Chamado','Finalizado'].map(label=>`<span class="${state===label?'current':''}">${label}</span>`).join('')}</div><p class="other-status-note">${state==='Cancelado'?'Operação cancelada':called?'Última chamada: '+new Date(called).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Aguardando chamada pelo WhatsApp'}</p><div class="ewm-buttons ewm-row-actions">${editable?`<button type="button" data-action="other-finish" data-id="${escapeHtml(op.id)}">Finalizar operação</button>`:''}${tools}</div></div>`;
