 const events=(op.ewmAudit||op.linhaDoTempo||[]).filter(e=>(!op.sapBaldeio?.updatedAtMs||getTimelineMs(e.timestampMs)>op.sapBaldeio.updatedAtMs)&&e.ewm===true&&Number.isInteger(e.toStage)&&e.toStage>=0&&e.toStage<=5&&getTimelineMs(e.timestampMs)>=start&&getTimelineMs(e.timestampMs)<=end).map(e=>({...e,ms:getTimelineMs(e.timestampMs)})).sort((a,b)=>a.ms-b.ms);
