  function buildReprintDriverData(op = {}) {
    const isDrop = reprintIsDrop(op);
    const telefoneViagem = (typeof getTelefoneFromOperacao === 'function' ? (getTelefoneFromOperacao(op) || '') : '') || reprintSheetPick(op, ['telefone', 'telefoneMotorista', 'celular', 'celularMotorista', 'phone', 'motoristaViagem.telefone', 'motoristaViagem.phone', 'dropHook.motoristaViagem.telefone']);
    const telefoneManobra = reprintSheetPick(op, ['motoristaManobraTelefone', 'dropMotoristaManobraTelefone', 'motoristaManobra.telefone', 'motoristaManobra.phone', 'dropHook.motoristaManobra.telefone']);
    const tripName = isDrop ? reprintGetDropViagem(op) : getReprintSheetMotorista(op);
    const manobraName = isDrop ? reprintGetDropManobra(op) : '';
    const tripCpf = isDrop ? reprintFormatCpf(reprintSheetPick(op, ['motoristaViagemCpf', 'dropMotoristaViagemCpf', 'motoristaViagem.cpf', 'dropHook.motoristaViagem.cpf', 'dropHookTripCpf', 'cpf'])) : getReprintSheetCpf(op);
    const manobraCpf = reprintFormatCpf(reprintSheetPick(op, ['motoristaManobraCpf', 'dropMotoristaManobraCpf', 'motoristaManobra.cpf', 'dropHook.motoristaManobra.cpf', 'dropHookManeuverCpf']));
    const truckPlate = reprintGetTruckPlate(op);
    const trailerPlate = reprintGetTrailerPlate(op);
    const maneuverPlate = reprintCleanPlate(reprintSheetPick(op, ['placaManobra', 'dropPlacaManobra', 'dropHook.placaManobra', 'maneuverPlate', 'dropHookManeuverPlate', 'motoristaManobra.truckPlate', 'dropHook.motoristaManobra.truckPlate']));
    const transportadora = reprintSheetPick(op, ['transportadora', 'carrier', 'carrierName', 'motoristaViagem.transportadora', 'dropHook.motoristaViagem.transportadora', 'motoristaManobra.transportadora']) || '';
    const vehicleType = reprintSheetPick(op, ['tipoVeiculo', 'vehicleType', 'vehicle', 'motoristaViagem.vehicleType', 'dropHook.motoristaViagem.vehicleType']) || '';
    const dropAlsoUnload = reprintBool(op.dropHookAlsoUnload ?? op.dropHook?.dropHookAlsoUnload ?? op.contabilizarDescarga ?? op.dropHook?.contabilizarDescarga);
    const originalMarkingMs = reprintGetOriginalMarkingMs(op);

    return {
      isDropHook: isDrop,
      originalMarkingMs,
      registrationTimeMs: originalMarkingMs,
      name: isDrop ? (manobraName || tripName) : tripName,
      cpf: isDrop ? (manobraCpf || tripCpf) : tripCpf,
      codigoMotorista: String(op.codigoMotorista || driverIndex.byCpf[cpf11(isDrop ? (manobraCpf || tripCpf) : tripCpf)]?.codigoMotorista || ''),
      phone: reprintFormatPhone(isDrop ? (telefoneManobra || telefoneViagem) : telefoneViagem),
      cnh: reprintSheetPick(op, ['cnh', 'cnhMotorista', 'motoristaViagem.cnh', 'motoristaManobra.cnh', 'dropHook.motoristaViagem.cnh', 'dropHook.motoristaManobra.cnh']),
      transportadora,
      truckPlate,
      trailerPlate,
      vehicleType,
      axles: reprintSheetPick(op, ['eixos', 'axles']),
      renavam: reprintSheetPick(op, ['renavam']),
      invoice: reprintSheetPick(op, ['invoice', 'notaFiscal', 'nf', 'numeroNotaFiscal']),
      printableDt: getReprintSheetDt(op),
      printableUnloadDt: reprintSheetPick(op, ['unloadDt', 'dtDescarga', 'printableUnloadDt', 'dropHook.dtDescarga']),
      controleDtAuto: reprintBool(op.controleDtAuto ?? op.controlDtAuto),
      controleDtCode: reprintSheetPick(op, ['controleDtCode', 'controlDtCode']),
      controleDtProduct: getReprintSheetProduto(op),
      controleDtPallets: reprintSheetPick(op, ['controleDtPallets', 'controlDtPallets', 'pallets', 'paletes']),
      controleDtPriority: reprintSheetPick(op, ['controleDtPriority', 'controlDtPriority']),
      controleDtLocal: reprintSheetPick(op, ['controleDtLocal', 'controlDtLocal']) || 'Fábrica',
      operacao: isDrop ? (dropAlsoUnload ? 'DROP & HOOK - CARGA E DESCARGA' : 'DROP & HOOK - CARGA') : getReprintSheetProduto(op),
      flowKey: reprintSheetPick(op, ['flowKey']),
      flowLabel: reprintSheetPick(op, ['flowLabel']),
      dropHookAlsoUnload: dropAlsoUnload,
      maneuverPlate,
      dropHookManeuverPlate: maneuverPlate,
      motoristaViagem: {
        nome: tripName,
        cpf: tripCpf,
        codigoMotorista: String(op.motoristaViagem?.codigoMotorista || driverIndex.byCpf[cpf11(tripCpf)]?.codigoMotorista || (!isDrop ? op.codigoMotorista : '') || ''),
        telefone: reprintFormatPhone(telefoneViagem),
        cnh: reprintSheetPick(op, ['motoristaViagemCnh', 'motoristaViagem.cnh', 'dropHook.motoristaViagem.cnh', 'cnh']),
        transportadora,
        truckPlate,
        trailerPlate,
        vehicleType
      },
      motoristaManobra: {
        nome: manobraName || (isDrop ? getReprintSheetMotorista(op) : ''),
        cpf: manobraCpf,
        codigoMotorista: String(op.motoristaManobra?.codigoMotorista || driverIndex.byCpf[cpf11(manobraCpf)]?.codigoMotorista || ''),
        telefone: reprintFormatPhone(telefoneManobra),
        cnh: reprintSheetPick(op, ['motoristaManobraCnh', 'motoristaManobra.cnh', 'dropHook.motoristaManobra.cnh']),
        transportadora: reprintSheetPick(op, ['motoristaManobra.transportadora', 'dropHook.motoristaManobra.transportadora']) || transportadora,
        truckPlate: maneuverPlate || truckPlate,
        trailerPlate,
        vehicleType
      }
    };
  }

  function buildReprintSheetDataArray(op = {}) {
    const agenda = reprintSplitAgenda(op);
    const dtRecord = reprintFindControleDt(op);
    const productRecord = reprintFindControleProduct(dtRecord);
    const produtoControle = reprintSheetPick(dtRecord || {}, ['productNameSnapshot', 'produto', 'productName'])
      || reprintSheetPick(productRecord || {}, ['name', 'nome', 'produto']);
    const quantidadeControle = reprintSheetPick(dtRecord || {}, ['pallets', 'paletes', 'quantidade', 'qtd']);
    const produto = produtoControle || getReprintSheetProduto(op);
    const quantidade = quantidadeControle || getReprintSheetQuantidade(op);
    const preCargaRecord = op?.__reprintPreCargaRecord;
    const preCargaMateriais = Array.isArray(preCargaRecord?.materiais)
      ? preCargaRecord.materiais.filter(item => item && (item.sku || item.descricao))
      : [];
    const savedRowsPaths = [
      'sheetDataArray',
      'folhaMarcacaoDados',
      'folhaMarcacao.itens',
      'folhaMarcacao.rows',
      'dadosImpressao.itens',
      'dadosImpressao.rows',
      'printPayload.sheetDataArray',
      'printPayload.rows',
      'dadosPlanilha',
      'resultados',
      'itens',
      'produtos'
    ];
    const getPath = (root, path) => path.split('.').reduce((value, key) => value?.[key], root);
    const savedRows = savedRowsPaths
      .map(path => getPath(op, path))
      .find(value => Array.isArray(value) && value.some(item => item && typeof item === 'object'))
      || reprintCollectOriginalRows(op);

    if (savedRows) {
      const normalizedRows = savedRows.map(item => ({
        [REPRINT_HEADER_MAP.dts]: reprintSheetPick(item, ['DTS', 'DT', 'dts', 'dt', 'numeroDt', 'numeroTransporte']),
        [REPRINT_HEADER_MAP.canal]: reprintSheetPick(item, ['CANAL', 'canal', 'canalSap', 'codigoCanal']),
        [REPRINT_HEADER_MAP.cliente]: reprintSheetPick(item, ['CLIENTE', 'cliente', 'destino', 'customer', 'NOME 1', 'NOME_1', 'NOME1', 'nomeCliente', 'destinatario']),
        [REPRINT_HEADER_MAP.produto]: getReprintSheetProduto(item),
        [REPRINT_HEADER_MAP.descricao]: reprintSheetPick(item, ['DESCRICAO', 'DESCRIÇÃO', 'descricao', 'description', 'produto']),
        [REPRINT_HEADER_MAP.plt]: reprintSheetPick(item, ['PLT', 'quantidade', 'qtd', 'quantity', 'pallets', 'paletes']) || quantidadeControle,
        [REPRINT_HEADER_MAP.deposito]: reprintSheetPick(item, ['DEPOSITO', 'DEPÓSITO', 'deposito', 'warehouse']),
        [REPRINT_HEADER_MAP.transportadora]: reprintSheetPick(item, ['TRANSPORTADORA', 'transportadora', 'carrier', 'carrierName']),
        [REPRINT_HEADER_MAP.data]: reprintSheetPick(item, ['DATA', 'data', 'dataAgenda', 'agendaData']),
        [REPRINT_HEADER_MAP.agenda]: reprintSheetPick(item, ['AGENDA', 'agenda', 'hora', 'horaAgenda']),
        [REPRINT_HEADER_MAP.xtAdicional]: reprintSheetPick(item, ['XT_ADICIONAL', 'xtAdicional', 'textoAdicional', 'observacao'])
      })).filter(item => Object.values(item).some(value => String(value || '').trim()));
      if (normalizedRows.length) return normalizedRows;
    }

    if (!produto && preCargaMateriais.length) {
      return preCargaMateriais.map(item => ({
        [REPRINT_HEADER_MAP.dts]: getReprintSheetDt(op),
        [REPRINT_HEADER_MAP.canal]: reprintSheetPick(op, ['canal', 'CANAL', 'canalSap', 'codigoCanal']) || '',
        [REPRINT_HEADER_MAP.cliente]: reprintSheetPick(op, ['clienteSap', 'nomeCliente', 'destinatario', 'recebedor', 'cliente', 'CLIENTE', 'destino', 'client', 'customer', 'NOME 1', 'NOME_1']) || '',
        [REPRINT_HEADER_MAP.produto]: String(item.sku || item.descricao || '').trim(),
        [REPRINT_HEADER_MAP.descricao]: String(item.descricao || item.sku || '').trim(),
        [REPRINT_HEADER_MAP.plt]: item.planejadoPaletes ?? (String(item.unidade || '').toUpperCase() === 'PLT' ? item.planejado : ''),
        [REPRINT_HEADER_MAP.deposito]: reprintSheetPick(op, ['deposito', 'DEPOSITO', 'DEPÓSITO', 'deposit', 'warehouse']) || '',
        [REPRINT_HEADER_MAP.transportadora]: reprintSheetPick(op, ['transportadora', 'TRANSPORTADORA', 'carrier', 'carrierName']) || '',
        [REPRINT_HEADER_MAP.data]: agenda.data,
        [REPRINT_HEADER_MAP.agenda]: agenda.hora,
        [REPRINT_HEADER_MAP.xtAdicional]: reprintSheetPick(op, ['xtAdicional', 'XT_ADICIONAL', 'textoAdicional', 'observacao']) || ''
      }));
    }

    return [{
      [REPRINT_HEADER_MAP.dts]: getReprintSheetDt(op),
      [REPRINT_HEADER_MAP.canal]: reprintSheetPick(op, ['canal', 'CANAL', 'canalSap', 'codigoCanal']) || '',
      [REPRINT_HEADER_MAP.cliente]: reprintSheetPick(op, ['clienteSap', 'nomeCliente', 'destinatario', 'recebedor', 'cliente', 'CLIENTE', 'destino', 'client', 'customer', 'NOME 1', 'NOME_1']) || '',
      [REPRINT_HEADER_MAP.produto]: produto,
      [REPRINT_HEADER_MAP.descricao]: reprintSheetPick(op, ['descricao', 'DESCRICAO', 'DESCRIÇÃO', 'description']) || produto,
      [REPRINT_HEADER_MAP.plt]: quantidade,
      [REPRINT_HEADER_MAP.deposito]: reprintSheetPick(op, ['deposito', 'DEPOSITO', 'DEPÓSITO', 'deposit', 'warehouse']) || '',
      [REPRINT_HEADER_MAP.transportadora]: reprintSheetPick(op, ['transportadora', 'TRANSPORTADORA', 'carrier', 'carrierName']) || '',
      [REPRINT_HEADER_MAP.data]: agenda.data,
      [REPRINT_HEADER_MAP.agenda]: agenda.hora,
      [REPRINT_HEADER_MAP.xtAdicional]: reprintSheetPick(op, ['xtAdicional', 'XT_ADICIONAL', 'textoAdicional', 'observacao']) || ''
    }];
  }

  function getReprintStatusFlags(op = {}) {
    const status = `${getReprintSheetStatus(op)} ${reprintSheetPick(op, ['priority', 'prioridade', 'statusPrioridade', 'classificacao', 'tipoPrioridade'])}`.toUpperCase();
    return {
      isPriority: status.includes('ADERENTE') || status.includes('PRIORIDADE'),
      isOtif: status.includes('OTIF'),
      isTop18: status.includes('TOP18') || status.includes('TOP 18'),
      isAntecipacao: status.includes('ANTECIPA'),
      isGradeQueimada: status.includes('GRADE QUEIMADA') || status.includes('QUEIMADA'),
      isAtrasado: status.includes('PERDA DE AGENDA') || status.includes('ATRAS')
    };
  }

  function buildReprintMarkingSheetHtml(op = {}) {
    const driverData = buildReprintDriverData(op);
    const storedPriority = typeof getStoredPrioritySnapshot === 'function' ? getStoredPrioritySnapshot(op) : {};
    driverData.printPriority = storedPriority;
    const sheetDataArray = buildReprintSheetDataArray(op);
    const flags = getReprintStatusFlags(op);
    const operationTag = driverData.operacao || getReprintSheetProduto(op) || getReprintSheetStatus(op) || '';
    const isManual = reprintBool(op.isManual ?? op.manual ?? op.manualOverride);
    const officialContent = buildReprintOfficialPrintableSheet(
      driverData,
      sheetDataArray,
      flags.isPriority,
      flags.isOtif,
      flags.isTop18,
      flags.isAntecipacao,
      flags.isGradeQueimada,
      flags.isAtrasado,
      isManual
    );
    const dt = escapeHtml(getReprintSheetDt(op) || 'sem DT');
    return `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Reimpressão - Folha de Marcação ${dt}</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #fff; color: #000; font-family: Arial, Helvetica, sans-serif; }
    #printable-area { width: 100%; }
    @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
    ${REPRINT_OFFICIAL_PRINT_CSS}
  </style>
<style>
body.heilog-app-v2 #baldeio-sap-import{background:#d6edde!important;color:#153c28!important;-webkit-text-fill-color:#153c28!important;border:2px solid #328756;border-radius:10px;padding:10px 14px;font-size:14px;font-weight:700}body.heilog-app-v2 .bs-dialog button{color:#15492c!important;-webkit-text-fill-color:#15492c!important}body.heilog-app-v2 .bs-dialog :is(h3,p,label,td,th,strong,small){color:#183e2b!important;-webkit-text-fill-color:#183e2b!important}
.bs-dialog{width:min(1250px,96vw)!important;max-width:1250px!important;max-height:92vh;overflow:auto;background:#fff;color:#183e2b}.bs-dialog label{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0}.bs-dialog input,.bs-dialog select{border:1px solid #9abbab;padding:8px;border-radius:7px;background:white;color:#183e2b}.bs-dialog button{background:#e1f0e6;color:#15492c!important;-webkit-text-fill-color:#15492c!important;border:1px solid #7da88c;border-radius:8px;padding:10px 14px;margin:5px;cursor:pointer}.bs-dialog button:disabled{opacity:.5}.bs-dialog :is(h3,p,label,td,th,strong,small){color:#183e2b!important;-webkit-text-fill-color:#183e2b!important}.bs-review{overflow:auto;max-height:50vh}.bs-review table{width:100%;font-size:13px;border-collapse:collapse;white-space:nowrap}.bs-review th,.bs-review td{padding:10px;border:1px solid #cedfd3;text-align:left}.bs-review th{background:#e2efe6;position:sticky;top:0}.bs-dialog [hidden]{display:none!important}
</style></head>
<body>
  <div id="printable-area">${officialContent}</div>
</body>
</html>`;
  }

  async function reprintMarkingSheet(op = {}) {
    if (window.__heilogReprintInProgress) {
      showToast('A reimpressão já está sendo preparada.', 'info');
      return;
    }
    window.__heilogReprintInProgress = true;

    if (!op || !op.id) {
      window.__heilogReprintInProgress = false;
      showToast('Não encontrei os dados salvos para reimprimir.', 'error');
      return;
    }

    let printHtml = '';
    try {
      // Gera tudo antes de abrir/imprimir. Assim, se houver algum dado faltando,
      // não fica uma janela about:blank vazia aberta no navegador.
      const enrichedOp = await reprintLoadDtDetails(op);
      printHtml = buildReprintMarkingSheetHtml(enrichedOp);
    } catch (error) {
      window.__heilogReprintInProgress = false;
      console.error('Erro ao montar a reimpressão da folha/checklist:', error);
      showToast('Não consegui montar a reimpressão. Veja o console para detalhes.', 'error');
      return;
    }

    // Impressão via iframe: funciona melhor quando o arquivo é aberto localmente (file://),
    // evitando bloqueio de pop-up/about:blank no Edge/Chrome.
    try {
      const oldFrame = document.getElementById('heilog-reprint-print-frame');
      if (oldFrame) oldFrame.remove();

      const frame = document.createElement('iframe');
      frame.id = 'heilog-reprint-print-frame';
      frame.title = 'Reimpressão da folha de marcação';
      frame.style.position = 'fixed';
      frame.style.right = '0';
      frame.style.bottom = '0';
      frame.style.width = '0';
      frame.style.height = '0';
      frame.style.border = '0';
      frame.style.opacity = '0';
      frame.style.pointerEvents = 'none';
      document.body.appendChild(frame);

      const frameDoc = frame.contentWindow.document;
      frameDoc.open();
      frameDoc.write(printHtml);
      frameDoc.close();

      setTimeout(() => {
        try {
          frame.contentWindow.focus();
          frame.contentWindow.print();
          showToast('Reimpressão da folha de marcação e checklist aberta.', 'success');
          setTimeout(() => { window.__heilogReprintInProgress = false; }, 1500);
        } catch (printError) {
          window.__heilogReprintInProgress = false;
          console.error('Erro ao abrir impressão pelo iframe:', printError);
          showToast('Não consegui abrir a impressão automática. Tente novamente ou use Ctrl+P.', 'error');
        }
      }, 450);
    } catch (error) {
      window.__heilogReprintInProgress = false;
      console.error('Erro ao preparar a reimpressão:', error);
      showToast('Não consegui abrir a reimpressão. Veja o console para detalhes.', 'error');
    }
  }

  // ==============================
  // CLICK TABELA + CONFIRM
  // ==============================
  function handleTableClick(e) {
    const actionEl = e.target.closest('[data-action]');
    if (!actionEl) return;
    e.preventDefault();

    const action = actionEl.dataset.action;
    const id = actionEl.dataset.id;
    if (!action || !id) return;
    if(isOperatorAccess()&&!['ewm-advance','ewm-reverse','details','occurrence','edit-occurrence','view-occurrence-images'].includes(action))return showToast('Seu perfil não permite esta ação.','error');

    selectedOperacao =
      (activeTab==='historico'?historicoData.find(op=>op.id===id):null) ||
      patioData.find(op => op.id === id) ||
      historicoData.find(op => op.id === id) ||
      ocorrenciasData.find(op => op.id === id);

    if (!selectedOperacao) {
      const occ = ocorrenciasData.find(o => o.id === id);
      if (occ) {
        selectedOperacao =
          patioData.find(p => p.id === occ.operacaoId) ||
          historicoData.find(h => h.id === occ.operacaoId) ||
          occ;
      }
    }
    if (!selectedOperacao) return;

    switch (action) {
      case 'other-finish': showConfirmModal('Finalizar esta operação e enviar ao Histórico?',()=>saveOtherFinish({...selectedOperacao})); break;
      case 'ewm-advance': openEwmTransition({...selectedOperacao},1); break;
      case 'ewm-reverse': openEwmTransition({...selectedOperacao},-1); break;
      case 'details': window.showDetailsModal(); break;
      case 'reprint-sheet': reprintMarkingSheet(selectedOperacao); break;
      case 'occurrence': window.showOccurrenceModal(); break;
      case 'finish': {
        if (requireSapUnlockForOperation(selectedOperacao, () => showConfirmModal('Tem certeza que deseja finalizar esta operação?', finalizarOperacao))) break;
        showConfirmModal('Tem certeza que deseja finalizar esta operação?', finalizarOperacao);
        break;
      }
      case 'whatsapp': {
        if (requireSapUnlockForOperation(selectedOperacao, () => openWhatsAppForOperation(selectedOperacao))) break;
        openWhatsAppForOperation(selectedOperacao);
        break;
      }
      case 'sap-whatsapp': {
        if (requireSapUnlockForOperation(selectedOperacao, () => openWhatsAppForOperation(selectedOperacao))) break;
        openWhatsAppForOperation(selectedOperacao);
        break;
      }
      case 'cancel': showConfirmModal(`Tem certeza que deseja cancelar a DT ${selectedOperacao.dt}? Esta ação não pode ser desfeita.`, cancelarOperacao); break;
      case 'edit-occurrence': window.showResolutionModal(); break;
      case 'view-occurrence-images': window.showOccurrenceImagesModal(); break;
    }
  }

  function showConfirmModal(text, callback) {
    document.getElementById('confirm-modal-text').textContent = text;
    confirmCallback = callback;
    document.getElementById('confirm-modal').classList.remove('hidden');
  }

