  function openDriverEditModalByKey(key) {
    const d = getDriverByKey(key);
    if (!d) { showToast("Motorista não encontrado.", "error"); return; }

    const primary = d._primary;
    if (!primary || !primary.collection || !primary.docId) {
      showToast("Cadastro sem origem para edição (drivers/motoristas).", "error");
      return;
    }

    selectedDriverEdit = d;
    selectedDriverEditSource = primary;

    const modal = document.getElementById('driver-edit-modal');
    const title = document.getElementById('driver-edit-title');
    const subtitle = document.getElementById('driver-edit-subtitle');
    const fields = document.getElementById('driver-edit-fields');
    const jsonPre = document.getElementById('driver-edit-json');

    const raw = primary.raw || {};
    const keys = Object.keys(raw || {})
      .filter(keyName => !DRIVER_AUTH_PROTECTED_FIELDS.has(keyName))
      .sort((a,b)=>a.localeCompare(b));

    // prioriza alguns campos comuns no topo
    const priority = ['name','motorista','cpf','phone','telefone','celular','truckPlate','trailerPlate','transportadora'];
    const ordered = [...new Set([...priority.filter(k => keys.includes(k)), ...keys.filter(k => !priority.includes(k))])];

    const mkRow = (k, v) => {
      const type = (v === null) ? 'null' : (Array.isArray(v) ? 'array' : typeof v);
      const label = escapeHtml(k);

      if (type === 'object' || type === 'array') {
        const txt = (() => { try { return JSON.stringify(v, null, 2); } catch(_) { return String(v ?? ''); } })();
        return `
          <div class="grid grid-cols-1 sm:grid-cols-3 gap-3 items-start">
            <div class="text-sm text-gray-300 pt-2">${label}</div>
            <textarea data-field="${escapeHtml(k)}" data-type="json"
              class="sm:col-span-2 bg-gray-700 border border-gray-600 rounded-lg py-2 px-3 text-white focus:outline-none focus:ring-2 focus:ring-blue-500 min-h-[96px] font-mono text-xs">${escapeHtml(txt)}</textarea>
          </div>`;
      }

      const sval = (v === undefined) ? '' : String(v);
      const dataType = (type === 'number') ? 'number' : (type === 'boolean') ? 'boolean' : 'string';

      return `
        <div class="grid grid-cols-1 sm:grid-cols-3 gap-3 items-center">
          <div class="text-sm text-gray-300">${label}</div>
          <input data-field="${escapeHtml(k)}" data-type="${dataType}" value="${escapeHtml(sval)}"
            class="sm:col-span-2 bg-gray-700 border border-gray-600 rounded-lg py-2 px-3 text-white focus:outline-none focus:ring-2 focus:ring-blue-500"/>
        </div>`;
    };

    fields.innerHTML = ordered.map(k => mkRow(k, raw[k])).join('');

    title.textContent = `Editar Motorista — ${d.name || raw.name || raw.motorista || 'Sem nome'}`;
    subtitle.textContent = `Origem: ${primary.collection}/${primary.docId}`;

    try { jsonPre.textContent = JSON.stringify(raw, null, 2); }
    catch (_) { jsonPre.textContent = String(raw); }

    modal.classList.remove('hidden');
  }

  function closeDriverEditModal() {
    const modal = document.getElementById('driver-edit-modal');
    if (modal) modal.classList.add('hidden');
    selectedDriverEdit = null;
    selectedDriverEditSource = null;
  }

  function coerceValueByType(type, strValue) {
    if (type === 'number') {
      const n = Number(strValue);
      return Number.isFinite(n) ? n : strValue;
    }
    if (type === 'boolean') {
      const v = String(strValue).trim().toLowerCase();
      if (v === 'true' || v === '1' || v === 'sim' || v === 'yes') return true;
      if (v === 'false' || v === '0' || v === 'nao' || v === 'não' || v === 'no') return false;
      return strValue;
    }
    if (type === 'json') {
      const t = String(strValue || '').trim();
      if (!t) return null;
      try { return JSON.parse(t); } catch (_) { return strValue; }
    }
    return strValue;
  }

  async function saveDriverEditModal() {
    if (!db || !selectedDriverEditSource) return;

    const { collection: col, docId, raw: originalRaw } = selectedDriverEditSource;
    if (!col || !docId) return;

    const container = document.getElementById('driver-edit-fields');
    const inputs = container ? Array.from(container.querySelectorAll('[data-field]')) : [];
    const updates = {};

    inputs.forEach(el => {
      const field = el.dataset.field;
      if (DRIVER_AUTH_PROTECTED_FIELDS.has(field)) return;
      const type = el.dataset.type || 'string';
      const v = coerceValueByType(type, el.value);

      const orig = (originalRaw || {})[field];
      if (!isDeepEqual(orig, v)) updates[field] = v;
    });

    if (!Object.keys(updates).length) {
      showToast("Sem alterações para salvar.", "info");
      closeDriverEditModal();
      return;
    }

    try {
      const ref = doc(db, `${activeDataPath()}/${col}`, docId);
      await updateDoc(ref, updates);
      showToast("Motorista atualizado com sucesso.", "success");
      closeDriverEditModal();
    } catch (err) {
      console.error("Erro ao atualizar motorista:", err);
      showToast("Erro ao salvar motorista (verifique permissões/regras).", "error");
    }
  }

  function addDriverEditField(name, value = '') {
    const fields = document.getElementById('driver-edit-fields');
    if (!fields) return;

    const safeName = String(name || '').trim();
    if (!safeName) return;
    if (DRIVER_AUTH_PROTECTED_FIELDS.has(safeName)) {
      showToast("Use os botões de autorização na tabela de Motoristas.", "info");
      return;
    }

    // evita duplicar campo
    const existing = fields.querySelector(`[data-field="${CSS.escape(safeName)}"]`);
    if (existing) { showToast("Esse campo já existe no formulário.", "info"); return; }

    const row = document.createElement('div');
    row.className = "grid grid-cols-1 sm:grid-cols-3 gap-3 items-center";
    row.innerHTML = `
      <div class="text-sm text-gray-300">${escapeHtml(safeName)}</div>
      <input data-field="${escapeHtml(safeName)}" data-type="string" value="${escapeHtml(String(value ?? ''))}"
        class="sm:col-span-2 bg-gray-700 border border-gray-600 rounded-lg py-2 px-3 text-white focus:outline-none focus:ring-2 focus:ring-blue-500"/>
    `;
    fields.appendChild(row);
  }



  // ============================================================
  // ============================================================
  // ✅ PRÉ-CARGA — Planejada → Em separação → Pronta
  // ============================================================
  const PRE_CARGA_STATUSES = ['planejada', 'em_separacao', 'pronta'];

  // Paletização oficial informada pela operação.
  // A planilha traz a quantidade em CX ou PAC; ambas usam caixasPorPalete.
  // O campo unidade fica apenas como informação da apresentação e não entra no cálculo.
  const PRE_CARGA_PALETIZACAO = Object.freeze({
    '903382': { unidade:12, caixasPorPalete:198 },
    '903384': { unidade:12, caixasPorPalete:198 },
    '903394': { unidade:12, caixasPorPalete:264 },
    '903401': { unidade:24, caixasPorPalete:42 },
    '903478': { unidade:24, caixasPorPalete:91 },
    '903480': { unidade:12, caixasPorPalete:96 },
    '903482': { unidade:24, caixasPorPalete:42 },
    '903483': { unidade:1, caixasPorPalete:8 },
    '903486': { unidade:1, caixasPorPalete:8 },
    '903489': { unidade:1, caixasPorPalete:8 },
    '903496': { unidade:1, caixasPorPalete:8 },
    '903996': { unidade:24, caixasPorPalete:91 },
    '904113': { unidade:12, caixasPorPalete:336 },
    '904502': { unidade:24, caixasPorPalete:42 },
    '904504': { unidade:12, caixasPorPalete:198 },
    '904507': { unidade:1, caixasPorPalete:8 },
    '904508': { unidade:12, caixasPorPalete:264 },
    '904721': { unidade:12, caixasPorPalete:520 },
    '904932': { unidade:12, caixasPorPalete:280 },
    '904952': { unidade:12, caixasPorPalete:280 },
    '904701': { unidade:24, caixasPorPalete:91 },
    '905163': { unidade:1, caixasPorPalete:8 },
    '904961': { unidade:12, caixasPorPalete:280 },
    '905291': { unidade:24, caixasPorPalete:104 },
    '903495': { unidade:1, caixasPorPalete:8 },
    '905451': { unidade:24, caixasPorPalete:91 },
    '904895': { unidade:8, caixasPorPalete:520 },
    '903750': { unidade:12, caixasPorPalete:280 },
    '905573': { unidade:24, caixasPorPalete:91 },
    '905572': { unidade:12, caixasPorPalete:280 }
  });

  const preCargaActor = () => {
    const session = dropManagerSession();
    return {
      uid: String(session.uid || ''),
      usuario: String(session.username || 'usuário')
    };
  };

  const preCargaPlate = (value = '') => String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 7);
  const preCargaNumber = (value, fallback = 0) => {
    if (typeof value === 'number') return Number.isFinite(value) ? Math.max(0, value) : fallback;
    let raw = String(value ?? '').trim().replace(/\s+/g, '');
    // Planilhas/CSVs em pt-BR podem entregar 135.450 como texto (separador de milhar).
    if (/^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(raw)) raw = raw.replace(/\./g, '').replace(',', '.');
    else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(raw)) raw = raw.replace(/,/g, '');
    else raw = raw.replace(',', '.');
    const number = Number(raw);
    return Number.isFinite(number) ? Math.max(0, number) : fallback;
  };
  const preCargaSkuConfig = (sku = '') => PRE_CARGA_PALETIZACAO[String(sku || '').trim()] || null;
  const preCargaQtyToPallets = (item = {}, quantity = 0) => {
    const qty = preCargaNumber(quantity);
    // A planilha de produção não possui coluna de unidade: ausência significa CX/PAC.
    const unit = String(item.unidade || 'CX').trim().toUpperCase();
    if (unit === 'PLT') return qty;
    const config = preCargaSkuConfig(item.sku) || {};
    const caixasPorPalete = preCargaNumber(item.caixasPorPalete ?? config.caixasPorPalete);
    if (!caixasPorPalete) return null;
    if (unit === 'CX' || unit === 'PAC') return qty / caixasPorPalete;
    return null;
  };
  const preCargaStatusLabel = (status = '') => ({
    planejada: 'Planejada',
    em_separacao: 'Em separação',
    pronta: 'Pronta'
  }[status] || 'Planejada');
  const preCargaFormatQty = (value = 0) => preCargaNumber(value).toLocaleString('pt-BR', { maximumFractionDigits: 2 });
  const preCargaFormatDate = (value = 0) => {
    const ms = Number(value || 0);
    return ms ? new Date(ms).toLocaleString('pt-BR', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' }) : '—';
  };
  const preCargaCollectionRef = () => collection(db, `${activeDataPath()}/pre_cargas`);

  function attachPreCargaSnapshot(force = false) {
    if (!db) return;
    const path = `${activeDataPath()}/pre_cargas`;
    if (!force && preCargaSnapshotUnsub && preCargaSnapshotPath === path) return;
    try { if (typeof preCargaSnapshotUnsub === 'function') preCargaSnapshotUnsub(); } catch (_) {}
    preCargaSnapshotPath = path;
    preCargaData = [];
    preCargaSnapshotUnsub = onSnapshot(
      query(collection(db, path), orderBy('updatedAtMs', 'desc'), limit(500)),
      snap => {
        preCargaData = snap.docs.map(d => ({ ...d.data(), id:d.id }));
        if (activeTab === 'pre-carga') renderPreCarga();
      },
      error => {
        console.warn('Pré-carga: falha ao carregar registros.', error);
        showToast('Não foi possível carregar as pré-cargas.', 'error');
      }
    );
  }

  function preCargaMaterialRow(material = {}) {
    return `
      <div class="pre-carga-material-row">
        <label><span>SKU</span><input data-pre-material="sku" type="text" maxlength="30" value="${escapeHtml(material.sku || '')}" placeholder="903489"></label>
        <label><span>Material</span><input data-pre-material="descricao" type="text" maxlength="120" value="${escapeHtml(material.descricao || '')}" placeholder="Descrição do produto"></label>
        <label><span>Planejado</span><input data-pre-material="planejado" type="number" min="0.01" step="0.01" value="${escapeHtml(material.planejado ?? '')}" placeholder="0"></label>
        <label><span>Separado</span><input data-pre-material="separado" type="number" min="0" step="0.01" value="${escapeHtml(material.separado ?? 0)}"></label>
        <label><span>Unidade</span><select data-pre-material="unidade">
          ${['CX','PAC','PLT'].map(unit => `<option value="${unit}" ${String(material.unidade || 'CX').toUpperCase() === unit ? 'selected' : ''}>${unit}</option>`).join('')}
        </select></label>
        <button type="button" class="pre-carga-remove-material" data-pre-carga-action="remove-material" title="Remover material" aria-label="Remover material">×</button>
      </div>`;
  }

  function addPreCargaMaterialRow(material = {}) {
    const rows = document.getElementById('pre-carga-material-rows');
    if (rows) rows.insertAdjacentHTML('beforeend', preCargaMaterialRow(material));
  }

  function closePreCargaModal() {
    const modal = document.getElementById('pre-carga-modal');
    if (modal) modal.hidden = true;
    preCargaEditingId = '';
  }

  function openPreCargaModal(record = null) {
    const modal = document.getElementById('pre-carga-modal');
    const form = document.getElementById('pre-carga-form');
    if (!modal || !form) return;
    form.reset();
    preCargaEditingId = String(record?.id || '');
    document.getElementById('pre-carga-modal-title').textContent = record ? `Editar pré-carga ${record.dt || ''}` : 'Nova pré-carga';
    document.getElementById('pre-carga-dt').value = record?.dt || '';
    document.getElementById('pre-carga-cavalo').value = record?.placaCavalo || '';
    document.getElementById('pre-carga-carreta').value = record?.placaCarreta || '';
    document.getElementById('pre-carga-motorista').value = record?.motorista || '';
    document.getElementById('pre-carga-transportadora').value = 'Ritmo';
    document.getElementById('pre-carga-rua').value = record?.rua || '';
    document.getElementById('pre-carga-doca').value = record?.doca || '';
    document.getElementById('pre-carga-prevista').value = record?.previstaAtMs
      ? new Date(Number(record.previstaAtMs) - new Date().getTimezoneOffset() * 60000).toISOString().slice(0,16)
      : '';
    document.getElementById('pre-carga-observacao').value = record?.observacao || '';
    const rows = document.getElementById('pre-carga-material-rows');
    if (rows) rows.innerHTML = '';
    const materials = Array.isArray(record?.materiais) && record.materiais.length ? record.materiais : [{}];
    materials.forEach(addPreCargaMaterialRow);
    modal.hidden = false;
    window.setTimeout(() => document.getElementById('pre-carga-dt')?.focus(), 0);
  }

  function collectPreCargaMaterials() {
    return Array.from(document.querySelectorAll('#pre-carga-material-rows .pre-carga-material-row')).map((row, index) => {
      const get = key => row.querySelector(`[data-pre-material="${key}"]`)?.value || '';
      const base = {
        id: String(row.dataset.materialId || `mat-${index + 1}`),
        sku: String(get('sku')).trim().toUpperCase(),
        descricao: String(get('descricao')).trim(),
        planejado: preCargaNumber(get('planejado')),
        separado: preCargaNumber(get('separado')),
        unidade: String(get('unidade') || 'CX').trim().toUpperCase()
      };
      const config = preCargaSkuConfig(base.sku);
      return {
        ...base,
        caixasPorPalete: config?.caixasPorPalete || null,
        planejadoPaletes: preCargaQtyToPallets(base, base.planejado),
        separadoPaletes: preCargaQtyToPallets(base, base.separado)
      };
    }).filter(item => item.sku || item.descricao || item.planejado > 0);
  }

  async function savePreCarga(event) {
    event.preventDefault();
    const materials = collectPreCargaMaterials();
    const dt = String(document.getElementById('pre-carga-dt')?.value || '').trim();
    const placaCavalo = preCargaPlate(document.getElementById('pre-carga-cavalo')?.value || '');
    const placaCarreta = preCargaPlate(document.getElementById('pre-carga-carreta')?.value || '');
    const motorista = String(document.getElementById('pre-carga-motorista')?.value || '').trim();
    const rua = String(document.getElementById('pre-carga-rua')?.value || '').trim();
    const doca = String(document.getElementById('pre-carga-doca')?.value || '').trim();
    const previstaValue = document.getElementById('pre-carga-prevista')?.value || '';
    const previstaAtMs = previstaValue ? new Date(previstaValue).getTime() : 0;
    const observacao = String(document.getElementById('pre-carga-observacao')?.value || '').trim();

    if (!dt || !placaCavalo || !placaCarreta || !motorista || !rua || !doca) {
      showToast('Preencha DT, placas, motorista, rua e doca.', 'error');
      return;
    }
    if (!materials.length || materials.some(item => (!item.sku && !item.descricao) || item.planejado <= 0)) {
      showToast('Adicione pelo menos um material com quantidade planejada.', 'error');
      return;
    }
    const semConversao = materials.find(item => item.unidade !== 'PLT' && preCargaQtyToPallets(item, item.planejado) === null);
    if (semConversao) {
      showToast(`O SKU ${semConversao.sku || 'informado'} não possui conversão cadastrada para ${semConversao.unidade}.`, 'error');
      return;
    }

    const now = Date.now();
    const actor = preCargaActor();
    const existing = preCargaEditingId ? preCargaData.find(item => item.id === preCargaEditingId) : null;
    const status = existing?.status || 'planejada';
    const history = Array.isArray(existing?.historico) ? existing.historico.slice(-99) : [];
    history.push({
      tipo: existing ? 'edicao' : 'criacao',
      status,
      atMs: now,
      porUid: actor.uid,
      por: actor.usuario
    });
    const payload = {
      dt,
      placaCavalo,
      placaCarreta,
      motorista,
      transportadora: 'Ritmo',
      rua,
      doca,
      previstaAtMs: Number.isFinite(previstaAtMs) ? previstaAtMs : 0,
      observacao,
      materiais: materials,
      status,
      excluida: false,
      statusChangedAtMs: Number(existing?.statusChangedAtMs || now),
      historico: history,
      updatedAtMs: now,
      updatedAt: serverTimestamp(),
      alteradoPorUid: actor.uid,
      alteradoPor: actor.usuario
    };

    const saveButton = document.getElementById('pre-carga-save');
    if (saveButton) { saveButton.disabled = true; saveButton.textContent = 'Salvando...'; }
    try {
      if (existing) {
        await setDoc(doc(db, `${activeDataPath()}/pre_cargas`, existing.id), payload, { merge:true });
      } else {
        await addDoc(preCargaCollectionRef(), {
          ...payload,
          createdAtMs: now,
          createdAt: serverTimestamp(),
          criadoPorUid: actor.uid,
          criadoPor: actor.usuario
        });
      }
      closePreCargaModal();
      showToast(existing ? 'Pré-carga atualizada.' : 'Pré-carga criada.', 'success');
    } catch (error) {
      console.error('Erro ao salvar pré-carga:', error);
      showToast('Não foi possível salvar a pré-carga.', 'error');
    } finally {
      if (saveButton) { saveButton.disabled = false; saveButton.textContent = 'Salvar pré-carga'; }
    }
  }

  function preCargaProgress(record = {}) {
    const materials = Array.isArray(record.materiais) ? record.materiais : [];
    const planned = materials.reduce((sum, item) => sum + (preCargaQtyToPallets(item, item.planejado) || 0), 0);
    const separated = materials.reduce((sum, item) => {
      const plannedPallets = preCargaQtyToPallets(item, item.planejado) || 0;
      const separatedPallets = preCargaQtyToPallets(item, item.separado) || 0;
      return sum + Math.min(separatedPallets, plannedPallets);
    }, 0);
    return { planned, separated, percent: planned ? Math.min(100, Math.round((separated / planned) * 100)) : 0 };
  }

  function preCargaCard(record = {}, deleted = false) {
    const materials = Array.isArray(record.materiais) ? record.materiais : [];
    const progress = preCargaProgress(record);
    const status = PRE_CARGA_STATUSES.includes(record.status) ? record.status : 'planejada';
    const startMs = Number(record.statusChangedAtMs || record.createdAtMs || Date.now());
    return `
      <article class="pre-carga-card" data-status="${escapeHtml(status)}" data-pre-carga-id="${escapeHtml(record.id || '')}">
        <header class="pre-carga-card-head">
          <div class="pre-carga-card-dt"><small>DT</small><strong>${escapeHtml(record.dt || '—')}</strong></div>
          <span class="pre-carga-stage-chip">${deleted ? 'Excluída' : escapeHtml(preCargaStatusLabel(status))}</span>
        </header>
        <div class="pre-carga-route"><span>Rua ${escapeHtml(record.rua || '—')}</span><span>→</span><span>Doca ${escapeHtml(record.doca || '—')}</span></div>
        <div class="pre-carga-meta">
          <span>Motorista<strong>${escapeHtml(record.motorista || '—')}</strong></span>
          <span>Transportadora<strong>Ritmo</strong></span>
          <span>Cavalo<strong>${escapeHtml(record.placaCavalo || '—')}</strong></span>
          <span>Carreta<strong>${escapeHtml(record.placaCarreta || '—')}</strong></span>
          <span>Previsto<strong>${escapeHtml(preCargaFormatDate(record.previstaAtMs))}</strong></span>
          <span>Separação<strong>${preCargaFormatQty(progress.separated)} / ${preCargaFormatQty(progress.planned)}</strong></span>
        </div>
        <div class="pre-carga-materials">
          ${materials.map(item => {
            const planned = preCargaNumber(item.planejado);
            const separated = preCargaNumber(item.separado);
            const percent = planned ? Math.min(100, Math.round((separated / planned) * 100)) : 0;
            const plannedPallets = preCargaQtyToPallets(item, planned);
            const separatedPallets = preCargaQtyToPallets(item, separated);
            const palletEquivalent = item.unidade && item.unidade !== 'PLT' && plannedPallets !== null
              ? `<small class="pre-carga-pallet-equivalent">≈ ${preCargaFormatQty(separatedPallets)}/${preCargaFormatQty(plannedPallets)} PLT</small>`
              : '';
            return `<div class="pre-carga-material">
              <div class="pre-carga-material-line"><strong>${escapeHtml(item.sku || 'SEM SKU')} · ${escapeHtml(item.descricao || 'Material')}</strong><span>${preCargaFormatQty(separated)}/${preCargaFormatQty(planned)} ${escapeHtml(item.unidade || 'PLT')}${palletEquivalent}</span></div>
              <div class="pre-carga-progress"><span style="width:${percent}%"></span></div>
            </div>`;
          }).join('')}
        </div>
        ${record.observacao ? `<p class="text-xs text-gray-500 mb-2">${escapeHtml(record.observacao)}</p>` : ''}
        <footer class="pre-carga-card-foot">
          <div class="pre-carga-timer-wrap">${deleted ? `Excluída ${escapeHtml(preCargaFormatDate(record.excluidaAtMs))}` : 'Tempo na etapa'}<span class="pre-carga-timer" data-pre-carga-start="${startMs}">${deleted ? '—' : formatMilliseconds(Math.max(0, Date.now() - startMs))}</span></div>
          <div class="pre-carga-card-actions">
            ${deleted ? `<button class="pre-carga-mini pre-carga-btn-soft" data-pre-carga-action="restore">Restaurar</button>` : `
              ${status !== 'planejada' ? `<button class="pre-carga-mini pre-carga-btn-soft" data-pre-carga-action="back">Voltar</button>` : ''}
              <button class="pre-carga-mini pre-carga-btn-soft" data-pre-carga-action="edit">Editar</button>
              ${status !== 'pronta' ? `<button class="pre-carga-mini pre-carga-btn-primary" data-pre-carga-action="next">Avançar</button>` : ''}
              <button class="pre-carga-mini pre-carga-btn-danger" data-pre-carga-action="delete">Excluir</button>
            `}
          </div>
        </footer>
      </article>`;
  }

  function renderPreCarga() {
    const content = document.getElementById('pre-carga-content');
    if (!content) return;
    const term = compact(document.getElementById('pre-carga-search')?.value || '');
    const visible = (preCargaData || []).filter(record => {
      if(!term)return true;
      const haystack = compact(`${record.dt || ''} ${record.placaCavalo || ''} ${record.placaCarreta || ''} ${record.motorista || ''} ${record.rua || ''} ${record.doca || ''} ${(record.materiais || []).map(item => `${item.sku || ''} ${item.descricao || ''}`).join(' ')}`);
      return !term || haystack.includes(term);
    });
    const active = visible.filter(record => record.excluida !== true);
    const deleted = visible.filter(record => record.excluida === true);
    const totals = active.reduce((acc, record) => {
      const progress = preCargaProgress(record);
      acc.planned += progress.planned;
      acc.separated += progress.separated;
      return acc;
    }, { planned:0, separated:0 });

    const summary = document.getElementById('pre-carga-summary');
    if (summary) summary.innerHTML = `
      <div class="pre-carga-kpi"><span>Total ativas</span><strong>${active.length}</strong></div>
      <div class="pre-carga-kpi"><span>Em separação</span><strong>${active.filter(item => item.status === 'em_separacao').length}</strong></div>
      <div class="pre-carga-kpi"><span>Prontas</span><strong>${active.filter(item => item.status === 'pronta').length}</strong></div>
      <div class="pre-carga-kpi"><span>Material separado (PLT)</span><strong>${preCargaFormatQty(totals.separated)}/${preCargaFormatQty(totals.planned)}</strong></div>`;

    PRE_CARGA_STATUSES.forEach(status => {
      const list = active.filter(record => (record.status || 'planejada') === status);
      const count = document.getElementById(`pre-carga-count-${status}`);
      const container = document.getElementById(`pre-carga-list-${status}`);
      if (count) count.textContent = String(list.length);
      if (container) container.innerHTML = list.map(record => preCargaCard(record)).join('') || '<div class="pre-carga-empty">Nenhuma pré-carga nesta etapa.</div>';
    });

    const deletedSection = document.getElementById('pre-carga-deleted');
    const deletedList = document.getElementById('pre-carga-list-deleted');
    const deletedCount = document.getElementById('pre-carga-count-deleted');
    if (deletedSection) deletedSection.hidden = !preCargaShowDeleted;
    if (deletedCount) deletedCount.textContent = String(deleted.length);
    if (deletedList) deletedList.innerHTML = deleted.map(record => preCargaCard(record, true)).join('') || '<div class="pre-carga-empty">Nenhuma pré-carga excluída.</div>';
    const toggle = document.getElementById('pre-carga-toggle-deleted');
    if (toggle) toggle.textContent = preCargaShowDeleted ? 'Ocultar excluídas' : `Ver excluídas (${deleted.length})`;
  }

  async function changePreCargaStatus(record, direction) {
    const currentIndex = Math.max(0, PRE_CARGA_STATUSES.indexOf(record.status || 'planejada'));
    const nextIndex = direction === 'back' ? currentIndex - 1 : currentIndex + 1;
    if (nextIndex < 0 || nextIndex >= PRE_CARGA_STATUSES.length) return;
    const nextStatus = PRE_CARGA_STATUSES[nextIndex];
    let justificativa = '';
    if (nextStatus === 'pronta') {
      const incomplete = (record.materiais || []).filter(item => preCargaNumber(item.separado) < preCargaNumber(item.planejado));
      if (incomplete.length) {
        justificativa = window.prompt('Há material ainda não separado. Informe a justificativa para concluir com divergência:') || '';
        if (!justificativa.trim()) {
          showToast('Para concluir com divergência, informe uma justificativa.', 'error');
          return;
        }
      }
    }
    const now = Date.now();
    const actor = preCargaActor();
    const history = Array.isArray(record.historico) ? record.historico.slice(-99) : [];
    history.push({ tipo:'status', de:record.status || 'planejada', para:nextStatus, atMs:now, porUid:actor.uid, por:actor.usuario, justificativa });
    const update = {
      status:nextStatus,
      statusChangedAtMs:now,
      updatedAtMs:now,
      updatedAt:serverTimestamp(),
      alteradoPorUid:actor.uid,
      alteradoPor:actor.usuario,
      historico:history
    };
    if (nextStatus === 'em_separacao' && !record.separacaoIniciadaAtMs) update.separacaoIniciadaAtMs = now;
    if (nextStatus === 'pronta') {
      update.prontaAtMs = now;
      update.divergenciaJustificativa = justificativa.trim();
    }
    try {
      await updateDoc(doc(db, `${activeDataPath()}/pre_cargas`, record.id), update);
      showToast(`Pré-carga movida para ${preCargaStatusLabel(nextStatus)}.`, 'success');
    } catch (error) {
      console.error('Erro ao avançar pré-carga:', error);
      showToast('Não foi possível alterar a etapa.', 'error');
    }
  }

  async function deletePreCarga(record) {
    if (!window.confirm(`Excluir a pré-carga da DT ${record.dt || ''}? Ela poderá ser restaurada.`)) return;
    const motivo = window.prompt('Informe o motivo da exclusão:');
    if (motivo === null) return;
    if (!String(motivo).trim()) {
      showToast('Informe o motivo da exclusão.', 'error');
      return;
    }
    const now = Date.now();
    const actor = preCargaActor();
    const history = Array.isArray(record.historico) ? record.historico.slice(-99) : [];
    history.push({ tipo:'exclusao', status:record.status || 'planejada', atMs:now, porUid:actor.uid, por:actor.usuario, motivo:String(motivo).trim() });
    try {
      await updateDoc(doc(db, `${activeDataPath()}/pre_cargas`, record.id), {
        excluida:true,
        excluidaAtMs:now,
        excluidaPorUid:actor.uid,
        excluidaPor:actor.usuario,
        exclusaoMotivo:String(motivo).trim(),
        updatedAtMs:now,
        updatedAt:serverTimestamp(),
        historico:history
      });
      showToast('Pré-carga excluída. Ela pode ser restaurada.', 'success');
    } catch (error) {
      console.error('Erro ao excluir pré-carga:', error);
      showToast('Não foi possível excluir a pré-carga.', 'error');
    }
  }

  async function restorePreCarga(record) {
    if (!window.confirm(`Restaurar a pré-carga da DT ${record.dt || ''}?`)) return;
    const now = Date.now();
    const actor = preCargaActor();
    const history = Array.isArray(record.historico) ? record.historico.slice(-99) : [];
    history.push({ tipo:'restauracao', status:record.status || 'planejada', atMs:now, porUid:actor.uid, por:actor.usuario });
    try {
      await updateDoc(doc(db, `${activeDataPath()}/pre_cargas`, record.id), {
        excluida:false,
        excluidaAtMs:0,
        exclusaoMotivo:'',
        updatedAtMs:now,
        updatedAt:serverTimestamp(),
        alteradoPorUid:actor.uid,
        alteradoPor:actor.usuario,
        historico:history
      });
      showToast('Pré-carga restaurada.', 'success');
    } catch (error) {
      console.error('Erro ao restaurar pré-carga:', error);
      showToast('Não foi possível restaurar a pré-carga.', 'error');
    }
  }

  function handlePreCargaBoardClick(event) {
    const button = event.target.closest('[data-pre-carga-action]');
    if (!button) return;
    if (button.dataset.preCargaAction === 'remove-material') {
      const row = button.closest('.pre-carga-material-row');
      const totalRows = document.querySelectorAll('#pre-carga-material-rows .pre-carga-material-row').length;
      if (totalRows > 1) row?.remove();
      else showToast('A pré-carga precisa ter pelo menos um material.', 'info');
      return;
    }
    const card = button.closest('[data-pre-carga-id]');
    const record = preCargaData.find(item => item.id === card?.dataset.preCargaId);
    if (!record) return;
    const action = button.dataset.preCargaAction;
    if (action === 'edit') openPreCargaModal(record);
    if (action === 'next' || action === 'back') changePreCargaStatus(record, action);
    if (action === 'delete') deletePreCarga(record);
    if (action === 'restore') restorePreCarga(record);
  }

  // ✅ CONTROLE DE DTs + SUGESTÃO AUTOMÁTICA PARA RITMO VAZIA
  // ============================================================
  const cdtCollectionPath = (name) => `${activeDataPath()}/${name}`;
  const cdtNow = () => Date.now();
  const cdtId = () => `cdt_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const cdtNum = (v) => Number(String(v ?? '').replace(',', '.')) || 0;
  const cdtClean = (v) => String(v ?? '').trim();
  const cdtCompact = (v) => String(v ?? '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Z0-9]/g, '');
  const cdtMoneyNum = (v) => (Number(v || 0)).toLocaleString('pt-BR');

  function cdtPriorityClass(priority) {
    const p = String(priority || '').toLowerCase();
    if (p.includes('alta')) return 'cdt-priority-alta';
    if (p.includes('baixa')) return 'cdt-priority-baixa';
    return 'cdt-priority-normal';
  }

  function cdtPriorityWeight(priority) {
    const p = String(priority || '').toLowerCase();
    if (p.includes('alta')) return 0;
    if (p.includes('normal')) return 1;
    if (p.includes('baixa')) return 2;
    return 3;
  }

  function cdtStatusPill(status) {
    if (status === 'Baixada') return `<span class="cdt-pill cdt-pill-ok">✅ Baixada</span>`;
    if (status === 'Reservada') return `<span class="cdt-pill cdt-pill-hold">🔒 Reservada</span>`;
    if (status === 'Cancelada') return `<span class="cdt-pill cdt-pill-stop">🚫 Cancelada</span>`;
    return `<span class="cdt-pill cdt-pill-wait">⏳ Pendente</span>`;
  }

  function cdtProductById(productId) {
    return controleDtProducts.find(x => x.id === productId || x._id === productId);
  }

  function cdtProductName(productId) {
    const p = cdtProductById(productId);
    return p?.name || p?.nome || p?.produto || 'Produto não localizado';
  }

  function cdtProductPriority(productId) {
    const p = cdtProductById(productId);
    return p?.priority || p?.prioridade || 'Normal';
  }

  function cdtProductLocal(productId) {
    return 'Fábrica';
  }

  function cdtProductCalc(productId) {
    const p = cdtProductById(productId) || {};
    const target = cdtNum(p.targetPallets ?? p.programado ?? p.target ?? p.paletesProgramados);
    const valid = controleDtDts.filter(dt => dt.productId === productId && dt.status !== 'Cancelada');
    const scheduled = valid.reduce((sum, dt) => sum + cdtNum(dt.pallets), 0);
    const reserved = valid.filter(dt => dt.status === 'Reservada').reduce((sum, dt) => sum + cdtNum(dt.pallets), 0);
    const done = valid.filter(dt => dt.status === 'Baixada').reduce((sum, dt) => sum + cdtNum(dt.pallets), 0);
    const pending = Math.max(target - scheduled, 0);
    const pct = target ? Math.round((scheduled / target) * 100) : 0;
    return { target, scheduled, reserved, done, pending, pct };
  }

  function cdtPersistLocal() {
    if (controleDtUsingFirestore) return;
    try {
      localStorage.setItem(CONTROLE_DT_LOCAL_KEY, JSON.stringify({
        products: controleDtProducts,
        dts: controleDtDts,
        movements: controleDtMovements
      }));
    } catch (err) {
      console.warn('Falha ao salvar Controle DT local:', err);
    }
  }

  function cdtLoadLocal() {
    try {
      const raw = localStorage.getItem(CONTROLE_DT_LOCAL_KEY);
      if (!raw) return;
      const parsed = JSON.parse(raw) || {};
      controleDtProducts = Array.isArray(parsed.products) ? parsed.products : [];
      controleDtDts = Array.isArray(parsed.dts) ? parsed.dts : [];
      controleDtMovements = Array.isArray(parsed.movements) ? parsed.movements : [];
    } catch (err) {
      console.warn('Falha ao ler Controle DT local:', err);
    }
  }

  async function cdtAddMovement(type, text, extra = {}) {
    const mov = { type, text, ...extra, createdAt: cdtNow() };
    if (controleDtUsingFirestore && db) {
      try {
        await addDoc(collection(db, cdtCollectionPath('controle_dt_movimentos')), mov);
        return;
      } catch (err) {
        console.warn('Falha ao gravar movimento DT no Firestore. Salvando local.', err);
        controleDtUsingFirestore = false;
      }
    }
    controleDtMovements.unshift({ ...mov, id: cdtId(), _id: cdtId() });
    controleDtMovements = controleDtMovements.slice(0, 120);
    cdtPersistLocal();
  }

  function cdtResetProductForm() {
    controleDtEditingProductId = '';
    const nameEl = document.getElementById('cdt-product-name');
    const targetEl = document.getElementById('cdt-product-target');
    const localEl = document.getElementById('cdt-product-local');
    const priorityEl = document.getElementById('cdt-product-priority');
    const addBtn = document.getElementById('cdt-add-product-btn');
    const cancelBtn = document.getElementById('cdt-cancel-product-edit-btn');
    if (nameEl) nameEl.value = '';
    if (targetEl) targetEl.value = '';
    if (localEl) localEl.value = 'Fábrica';
    if (priorityEl) priorityEl.value = 'Normal';
    if (addBtn) addBtn.textContent = 'Adicionar produto';
    if (cancelBtn) cancelBtn.classList.add('hidden');
  }

  function cdtStartEditProduct(productId) {
    const p = cdtProductById(productId);
    if (!p) return showToast('Produto não encontrado.', 'error');
    controleDtEditingProductId = p._id || p.id || productId;
    const nameEl = document.getElementById('cdt-product-name');
    const targetEl = document.getElementById('cdt-product-target');
    const localEl = document.getElementById('cdt-product-local');
    const priorityEl = document.getElementById('cdt-product-priority');
    const addBtn = document.getElementById('cdt-add-product-btn');
    const cancelBtn = document.getElementById('cdt-cancel-product-edit-btn');
    if (nameEl) nameEl.value = p.name || p.nome || p.produto || '';
    if (targetEl) targetEl.value = cdtNum(p.targetPallets ?? p.programado ?? p.target ?? p.paletesProgramados) || '';
    if (localEl) localEl.value = p.local || 'Fábrica';
    if (priorityEl) priorityEl.value = p.priority || p.prioridade || 'Normal';
    if (addBtn) addBtn.textContent = 'Salvar produto';
    if (cancelBtn) cancelBtn.classList.remove('hidden');
    nameEl?.focus();
    showToast('Produto em edição. Ajuste os campos e clique em Salvar produto.', 'info');
  }

  async function cdtAddProduct() {
    const name = cdtClean(document.getElementById('cdt-product-name')?.value);
    const target = cdtNum(document.getElementById('cdt-product-target')?.value);
    const local = 'Fábrica';
    const priority = cdtClean(document.getElementById('cdt-product-priority')?.value) || 'Normal';

    if (!name) return showToast('Informe o produto.', 'error');
    if (!target || target <= 0) return showToast('Informe o programado em paletes.', 'error');

    if (controleDtEditingProductId) {
      return cdtUpdateProduct(controleDtEditingProductId, { name, targetPallets: target, local, priority });
    }

    const item = { name, targetPallets: target, local, priority, createdAt: cdtNow(), updatedAt: cdtNow() };
    try {
      if (controleDtUsingFirestore && db) {
        await addDoc(collection(db, cdtCollectionPath('controle_dt_produtos')), item);
      } else {
        const id = cdtId();
        controleDtProducts.unshift({ ...item, id, _id: id });
        cdtPersistLocal();
      }
      await cdtAddMovement('Produto', `Produto ${name} programado com ${cdtMoneyNum(target)} paletes • ${local} • ${priority}`);
      cdtResetProductForm();
      showToast('Produto programado adicionado.', 'success');
      renderControleDt();
    } catch (err) {
      console.error(err);
      showToast('Erro ao adicionar produto.', 'error');
    }
  }

  async function cdtUpdateProduct(productId, patch) {
    const p = cdtProductById(productId);
    if (!p) return showToast('Produto não encontrado.', 'error');
    const realId = p._id || p.id || productId;
    const oldName = p.name || p.nome || p.produto || 'Produto';
    const updates = { ...patch, updatedAt: cdtNow() };
    const linkedDts = (controleDtDts || []).filter(dt => String(dt.productId || '') === String(realId) || String(dt.productId || '') === String(productId));

    try {
      if (controleDtUsingFirestore && db && p._id) {
        await updateDoc(doc(db, cdtCollectionPath('controle_dt_produtos'), realId), updates);

        if (linkedDts.length) {
          let batch = writeBatch(db);
          let count = 0;
          for (const dt of linkedDts) {
            const dtRealId = dt._id || dt.id;
            if (!dtRealId) continue;
            batch.update(doc(db, cdtCollectionPath('controle_dt_dts'), dtRealId), {
              productNameSnapshot: patch.name,
              prioritySnapshot: patch.priority,
              local: 'Fábrica',
              updatedAt: cdtNow()
            });
            count += 1;
            if (count % 450 === 0) {
              await batch.commit();
              batch = writeBatch(db);
            }
          }
          if (count % 450 !== 0) await batch.commit();
        }
      } else {
        Object.assign(p, updates);
        linkedDts.forEach(dt => {
          dt.productNameSnapshot = patch.name;
          dt.prioritySnapshot = patch.priority;
          dt.local = 'Fábrica';
          dt.updatedAt = cdtNow();
        });
        cdtPersistLocal();
      }
      await cdtAddMovement('Produto', `Produto ${oldName} editado para ${patch.name} • ${cdtMoneyNum(patch.targetPallets)} pal • ${patch.local} • ${patch.priority}`);
      cdtResetProductForm();
      showToast('Produto atualizado.', 'success');
      renderControleDt();
    } catch (err) {
      console.error(err);
      showToast('Erro ao editar produto.', 'error');
    }
  }

  function cdtConfirmDeleteProduct(productId) {
    const p = cdtProductById(productId);
    if (!p) return;
    const name = p.name || p.nome || p.produto || 'produto';
    showConfirmModal(`Excluir o produto ${name}? As DTs já criadas serão mantidas com o nome congelado.`, () => cdtDeleteProduct(productId));
  }

  async function cdtDeleteProduct(productId) {
    const p = cdtProductById(productId);
    if (!p) return;
    const realId = p._id || p.id || productId;
    const name = p.name || p.nome || p.produto || 'Produto';
    try {
      if (controleDtUsingFirestore && db && p._id) {
        await deleteDoc(doc(db, cdtCollectionPath('controle_dt_produtos'), realId));
      } else {
        controleDtProducts = controleDtProducts.filter(x => String(x.id || x._id || '') !== String(realId));
        cdtPersistLocal();
      }
      if (String(controleDtEditingProductId || '') === String(realId)) cdtResetProductForm();
      await cdtAddMovement('Produto', `Produto ${name} excluído. DTs já criadas foram mantidas.`);
      renderControleDt();
      showToast('Produto excluído.', 'success');
    } catch (err) {
      console.error(err);
      showToast('Erro ao excluir produto.', 'error');
    }
  }

  async function cdtAddDt() {
    const code = cdtClean(document.getElementById('cdt-dt-code')?.value);
    const productId = cdtClean(document.getElementById('cdt-dt-product')?.value);
    const pallets = cdtNum(document.getElementById('cdt-dt-pallets')?.value);
    const local = 'Fábrica';

    if (!code) return showToast('Informe o número da DT.', 'error');
    if (!productId) return showToast('Selecione um produto pendente.', 'error');
    if (!pallets || pallets <= 0) return showToast('Informe os paletes da DT.', 'error');

    const duplicate = controleDtDts.some(dt => cdtCompact(dt.code) === cdtCompact(code) && dt.status !== 'Cancelada');
    if (duplicate) return showToast('Já existe uma DT com esse número.', 'error');

    const calc = cdtProductCalc(productId);
    if (calc.pending <= 0) return showToast('Esse produto já atingiu o programado.', 'error');

    const item = {
      code,
      productId,
      productNameSnapshot: cdtProductName(productId),
      pallets,
      local,
      prioritySnapshot: cdtProductPriority(productId),
      status: 'Pendente',
      createdAt: cdtNow(),
      updatedAt: cdtNow()
    };

    try {
      if (controleDtUsingFirestore && db) {
        await addDoc(collection(db, cdtCollectionPath('controle_dt_dts')), item);
      } else {
        const id = cdtId();
        controleDtDts.unshift({ ...item, id, _id: id });
        cdtPersistLocal();
      }
      await cdtAddMovement('DT', `DT ${code} criada • ${cdtProductName(productId)} • ${cdtMoneyNum(pallets)} pal • ${local}`);
      document.getElementById('cdt-dt-code').value = '';
      document.getElementById('cdt-dt-pallets').value = '';
      showToast('DT criada.', 'success');
      renderControleDt();
    } catch (err) {
      console.error(err);
      showToast('Erro ao criar DT.', 'error');
    }
  }

  async function cdtUpdateDt(dtId, patch, movementText = '') {
    const dt = controleDtDts.find(x => x.id === dtId || x._id === dtId);
    if (!dt) return;
    const realId = dt._id || dt.id || dtId;
    try {
      if (controleDtUsingFirestore && db && dt._id) {
        await updateDoc(doc(db, cdtCollectionPath('controle_dt_dts'), realId), { ...patch, updatedAt: cdtNow() });
      } else {
        Object.assign(dt, patch, { updatedAt: cdtNow() });
        cdtPersistLocal();
      }
      if (movementText) await cdtAddMovement('Movimentação', movementText, { dt: dt.code || '' });
      renderControleDt();
    } catch (err) {
      console.error(err);
      showToast('Erro ao atualizar DT.', 'error');
    }
  }

  function cdtIsEligibleAutomaticOperation(op = {}) {
    if (op.controleDtAuto === true || op.controlDtAuto === true) return true;
    if (typeof isDropHookOperation === 'function' && isDropHookOperation(op)) return true;
    const operationBlob = cdtCompact([
      op.operacao,
      op.operation,
      op.flowKey,
      op.flowLabel,
      op.tipo,
      op.tipoMarcacao,
      op.presetTransportadora
    ].filter(Boolean).join(' '));
    return operationBlob.includes('BALDEIO') || operationBlob.includes('RITMO');
  }

  function cdtFindLinkedDtForOperation(op = {}) {
    if (!cdtIsEligibleAutomaticOperation(op)) return null;
    const explicitId = String(op.controleDtId || op.controlDtId || '').trim();
    if (explicitId) {
      const byId = (controleDtDts || []).find(item => String(item._id || item.id || '') === explicitId);
      if (byId) return byId;
    }

    const operationCode = cdtCompact(op.controleDtCode || op.controlDtCode || op.dt || '');
    if (!operationCode) return null;
    return (controleDtDts || []).find(item => cdtCompact(item.code || '') === operationCode) || null;
  }

  function cdtOperationStatusPatch(status, changedAt = cdtNow()) {
    if (status === 'Baixada') {
      return {
        status: 'Baixada',
        completedAt: changedAt,
        completionSource: 'painel_operacao',
        updatedAt: changedAt
      };
    }

    return {
      status: 'Pendente',
      reservedAt: null,
      reservedForPlate: '',
      reservedTrailerPlate: '',
      reservedTruckPlate: '',
      reservedSourceId: '',
      reservedSource: '',
      reservedMode: '',
      reservedOperation: '',
      reservationReleasedAt: changedAt,
      reservationReleaseReason: 'operação cancelada no painel',
      updatedAt: changedAt
    };
  }

  function cdtAddOperationTransitionToBatch(batch, op = {}, status = 'Baixada', changedAt = cdtNow()) {
    const linkedDt = cdtFindLinkedDtForOperation(op);
    const linkedId = linkedDt?._id || linkedDt?.id || String(op.controleDtId || '').trim();
    if (!linkedId || !batch) return false;
    const patch = cdtOperationStatusPatch(status, changedAt);
    batch.set(doc(db, cdtCollectionPath('controle_dt_dts'), linkedId), patch, { merge: true });
    if (linkedDt) Object.assign(linkedDt, patch);
    return true;
  }

  async function cdtSyncOperationStatus(op = {}, status = 'Baixada', changedAt = cdtNow()) {
    const linkedDt = cdtFindLinkedDtForOperation(op);
    const linkedId = linkedDt?._id || linkedDt?.id || String(op.controleDtId || '').trim();
    if (!linkedId || !db) return false;
    const patch = cdtOperationStatusPatch(status, changedAt);
    await setDoc(doc(db, cdtCollectionPath('controle_dt_dts'), linkedId), patch, { merge: true });
    if (linkedDt) Object.assign(linkedDt, patch);
    await cdtAddMovement(
      'Automação',
      status === 'Baixada'
        ? `DT ${linkedDt?.code || op.controleDtCode || op.dt || ''} baixada ao concluir a operação`
        : `DT ${linkedDt?.code || op.controleDtCode || op.dt || ''} devolvida para Pendente após cancelamento`
    );
    renderControleDt();
    return true;
  }

  async function cdtReserveDt(dtId, plate, sourceOp = {}) {
    const dt = controleDtDts.find(x => x.id === dtId || x._id === dtId);
    if (!dt) return showToast('DT não encontrada.', 'error');
    if ((dt.status || 'Pendente') !== 'Pendente') return showToast('Essa DT não está pendente.', 'error');

    const patch = {
      status: 'Reservada',
      reservedAt: cdtNow(),
      reservedForPlate: plate || '',
      reservedSourceId: sourceOp?.id || '',
      reservedSource: sourceOp?._src || ''
    };
    await cdtUpdateDt(dtId, patch, `DT ${dt.code} reservada para placa ${plate || 'sem placa'}`);
    showToast(`DT ${dt.code} reservada para ${plate || 'placa sem identificação'}.`, 'success');
  }

  function cdtConfirmReserve(dtId, plate, sourceId, sourceSrc) {
    const sourceOp = [...(patioData || []).map(x => ({...x, _src:'patio'})), ...(historicoData || []).map(x => ({...x, _src:'historico'}))]
      .find(x => String(x.id || '') === String(sourceId || '') && String(x._src || '') === String(sourceSrc || '')) || { id: sourceId, _src: sourceSrc };
    showConfirmModal(`Reservar essa DT para a placa ${plate || 'sem placa'}?`, () => cdtReserveDt(dtId, plate, sourceOp));
  }

  function cdtConfirmStatus(dtId, status) {
    const dt = controleDtDts.find(x => x.id === dtId || x._id === dtId);
    if (!dt) return;
    const label = status === 'Pendente' ? 'devolver para pendente' : status.toLowerCase();
    showConfirmModal(`Deseja ${label} a DT ${dt.code}?`, () => {
      const patch = { status };
      if (status === 'Pendente') {
        Object.assign(patch, {
          reservedAt: null,
          reservedForPlate: '',
          reservedTrailerPlate: '',
          reservedTruckPlate: '',
          reservedSourceId: '',
          reservedSource: '',
          reservedMode: ''
        });
      }
      if (status === 'Baixada') patch.completedAt = cdtNow();
      if (status === 'Cancelada') patch.cancelledAt = cdtNow();
      cdtUpdateDt(dtId, patch, `DT ${dt.code} alterada para ${status}`);
    });
  }

  function cdtIsZeroOnlyValue(value) {
    if (value === null || value === undefined) return false;
    if (typeof value === 'number') return value === 0;
    if (Array.isArray(value)) {
      const usable = value.filter(v => String(v ?? '').trim() !== '');
      return usable.length > 0 && usable.every(cdtIsZeroOnlyValue);
    }
    if (typeof value === 'object') return false;
    const raw = String(value ?? '').trim();
    return /^0+$/.test(raw);
  }

  function cdtIsTimestampOnlyDtMarker(value) {
    if (value === null || value === undefined || typeof value === 'object') return false;
    const raw = String(value ?? '').trim().replace(/\D/g, '');
    // Exemplo real informado: 20260531182658 = YYYYMMDDHHMMSS.
    // Esse padrão entra como DT vazia apenas quando estiver em campo de DT da Ritmo.
    if (!/^(20)\d{10}(\d{2})?$/.test(raw)) return false;
    const year = Number(raw.slice(0, 4));
    const month = Number(raw.slice(4, 6));
    const day = Number(raw.slice(6, 8));
    const hour = Number(raw.slice(8, 10));
    const minute = Number(raw.slice(10, 12));
    const second = raw.length >= 14 ? Number(raw.slice(12, 14)) : 0;
    if (year < 2020 || year > 2099 || month < 1 || month > 12 || day < 1 || day > 31) return false;
    if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59) return false;
    const dt = new Date(year, month - 1, day, hour, minute, second);
    return dt.getFullYear() === year && dt.getMonth() === month - 1 && dt.getDate() === day;
  }

  function cdtIsVaziaDtMarkerValue(value) {
    if (Array.isArray(value)) {
      const usable = value.filter(v => String(v ?? '').trim() !== '');
      return usable.length > 0 && usable.every(cdtIsVaziaDtMarkerValue);
    }
    return cdtIsZeroOnlyValue(value) || cdtIsTimestampOnlyDtMarker(value);
  }

  function cdtIsDtFieldKey(key) {
    const k = cdtCompact(key);
    return (
      k === 'DT' ||
      k === 'DTS' ||
      k === 'NUMERODT' ||
      k === 'NRODT' ||
      k === 'CODDT' ||
      k === 'CODIGODT' ||
      k === 'DTCODE' ||
      k === 'DTCARGA' ||
      k === 'DTDESCARGA' ||
      k === 'DTDESCARGA' ||
      k === 'DOCUMENTOTRANSPORTE' ||
      k === 'TRANSPORTDOCUMENT' ||
      k.includes('NUMERODT') ||
      k.includes('CODIGODT') ||
      k.includes('DOCUMENTOTRANSPORTE')
    );
  }

  function cdtHasZeroOnlyDtMarker(op = {}) {
    const directKeys = [
      'dt', 'DT', 'dts', 'DTS', 'numeroDt', 'numeroDT', 'nroDt', 'codDt', 'codigoDt',
      'dtCode', 'dt_code', 'dtCarga', 'dtDescarga', 'documentoTransporte',
      'documento_transporte', 'transportDocument'
    ];

    for (const key of directKeys) {
      if (Object.prototype.hasOwnProperty.call(op, key) && cdtIsVaziaDtMarkerValue(op[key])) return true;
    }

    const walk = (obj, insideDtContext = false, depth = 0) => {
      if (!obj || typeof obj !== 'object' || depth > 4) return false;
      for (const [key, value] of Object.entries(obj)) {
        const dtContext = insideDtContext || cdtIsDtFieldKey(key);
        if (dtContext && cdtIsVaziaDtMarkerValue(value)) return true;
        if (value && typeof value === 'object' && !Array.isArray(value) && walk(value, dtContext, depth + 1)) return true;
      }
      return false;
    };

    return walk(op);
  }

  function cdtGetOpTime(op = {}) {
    return toMs(op.registrationTime || op.timestamp || op.createdAt || op.created_at || op.finishedTime) || cdtNow();
  }

  function cdtIsRitmoVaziaOp(op = {}) {
    if (!isRitmoOp(op)) return false;
    if (isLatasVaziasOp(op)) return true;
    if (cdtHasZeroOnlyDtMarker(op)) return true;
    try {
      const blob = JSON.stringify(op).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/0/g, 'O').replace(/1/g, 'I');
      return (
        blob.includes('VAZIA') ||
        blob.includes('VAZIO') ||
        blob.includes('VAZIAS') ||
        blob.includes('VAZIOS') ||
        blob.includes('CARRETA VAZ') ||
        blob.includes('STATUS":"VAZ') ||
        blob.includes('SITUACAO":"VAZ')
      );
    } catch (_) {
      return false;
    }
  }

  function cdtLocalFromOp(op = {}) {
    const raw = op.origem || op.local || op.deposito || op.depósito || op.base || op.unidade || op.destino || op.localOrigem || op.origin || '';
    const s = String(raw || '').toLowerCase();
    if (s.includes('heilo')) return 'Heilo';
    if (s.includes('fabr') || s.includes('jac')) return 'Fábrica';
    if (s.includes('armaz')) return 'Armazém externo';
    return '';
  }

  function cdtIsClosedPatioSuggestionOp(op = {}) {
    const statusBlob = cdtCompact([
      op.status,
      op.situacao,
      op.situação,
      op.estado,
      op.statusOperacao,
      op.status_global,
      op.statusGlobal
    ].filter(Boolean).join(' '));

    return [
      'FINALIZADO', 'FINALIZADA',
      'CANCELADO', 'CANCELADA',
      'BAIXADO', 'BAIXADA',
      'CONCLUIDO', 'CONCLUIDA',
      'ENCERRADO', 'ENCERRADA'
    ].some(term => statusBlob.includes(term));
  }

  function cdtGetLatestRitmoVazias() {
    const since = cdtNow() - (36 * 3600 * 1000);
    const ops = (patioData || [])
      .map(op => ({ ...op, _src: 'patio', _rt: cdtGetOpTime(op) }))
      .filter(op => op._rt >= since && !cdtIsClosedPatioSuggestionOp(op) && cdtIsRitmoVaziaOp(op))
      .sort((a, b) => b._rt - a._rt);

    const seen = new Set();
    const rows = [];
    ops.forEach(op => {
      const plate = plateKey(op, 'carreta') || plateKey(op, 'cavalo') || 'SEM PLACA';
      const key = cdtCompact(plate);
      if (seen.has(key)) return;
      seen.add(key);
      rows.push({ op, plate, local: cdtLocalFromOp(op), ms: op._rt });
    });
    return rows.slice(0, 8);
  }

  function cdtAvailableDts(localPref = '') {
    return (controleDtDts || [])
      .filter(dt => (dt.status || 'Pendente') === 'Pendente')
      .filter(dt => cdtCompact(dt.local || 'Fábrica') === 'FABRICA')
      .sort((a, b) => {
        const pa = cdtPriorityWeight(a.prioritySnapshot || cdtProductPriority(a.productId));
        const pb = cdtPriorityWeight(b.prioritySnapshot || cdtProductPriority(b.productId));
        return pa - pb || cdtNum(a.createdAt) - cdtNum(b.createdAt) || String(a.code || '').localeCompare(String(b.code || ''), 'pt-BR');
      });
  }

  function cdtRenderSelects() {
    const productSelect = document.getElementById('cdt-dt-product');

    if (productSelect) {
      const options = (controleDtProducts || [])
        .filter(p => {
          const id = p.id || p._id;
          if (!id) return false;
          return cdtProductCalc(id).pending > 0;
        })
        .sort((a,b) => cdtPriorityWeight(a.priority || a.prioridade) - cdtPriorityWeight(b.priority || b.prioridade) || String(a.name || '').localeCompare(String(b.name || ''), 'pt-BR'));

      productSelect.innerHTML = options.length
        ? options.map(p => {
            const id = p.id || p._id;
            const calc = cdtProductCalc(id);
            return `<option value="${escapeHtml(id)}">${escapeHtml(p.name || p.nome || 'Produto')} • falta criar ${cdtMoneyNum(calc.pending)} pal</option>`;
          }).join('')
        : `<option value="">Todos os produtos atingiram o programado</option>`;
    }

    cdtRenderManualReserveSelect();
  }

  function cdtPlateInputValue(id) {
    return cdtClean(document.getElementById(id)?.value).toUpperCase().replace(/\s+/g, '');
  }

  function cdtDtLinkLabel(dt = {}) {
    const trailer = cdtClean(dt.reservedTrailerPlate || dt.trailerPlate || '');
    const truck = cdtClean(dt.reservedTruckPlate || dt.truckPlate || '');
    if (trailer && truck) return `Carreta ${trailer} • Cavalo ${truck}`;
    if (trailer) return `Carreta ${trailer}`;
    if (truck) return `Cavalo ${truck}`;
    if (dt.reservedForPlate) return `Placa ${dt.reservedForPlate}`;
    return '—';
  }

  function cdtRenderManualReserveSelect() {
    const select = document.getElementById('cdt-manual-dt-select');
    const preview = document.getElementById('cdt-manual-dt-preview');
    if (!select) return;

    const previous = select.value || '';
    const localFilterValues = getMultiSelectValues('cdt-manual-local-filter');
    const rows = cdtAvailableDts(localFilterValues);

    select.innerHTML = rows.length
      ? rows.map(dt => {
          const id = dt._id || dt.id || '';
          const label = `${dt.code || 'DT sem número'} • ${dt.productNameSnapshot || cdtProductName(dt.productId)} • ${cdtMoneyNum(dt.pallets)} pal • ${dt.local || ''}`;
          return `<option value="${escapeHtml(id)}">${escapeHtml(label)}</option>`;
        }).join('')
      : `<option value="">Nenhuma DT pendente disponível</option>`;

    if (previous && rows.some(dt => String(dt._id || dt.id || '') === String(previous))) {
      select.value = previous;
    }

    cdtUpdateManualReservePreview();
  }

  function cdtUpdateManualReservePreview() {
    const select = document.getElementById('cdt-manual-dt-select');
    const preview = document.getElementById('cdt-manual-dt-preview');
    if (!select || !preview) return;
    const dtId = select.value || '';
    const dt = controleDtDts.find(x => String(x.id || x._id || '') === String(dtId));
    if (!dt) {
      preview.textContent = 'Cadastre ou libere uma DT pendente para reservar manualmente.';
      return;
    }
    preview.textContent = `${dt.code || 'DT'} • ${dt.productNameSnapshot || cdtProductName(dt.productId)} • ${cdtMoneyNum(dt.pallets)} pal • ${dt.local || ''} • ${dt.prioritySnapshot || cdtProductPriority(dt.productId)}`;
  }

  function cdtResetManualReserveForm() {
    const trailer = document.getElementById('cdt-manual-trailer');
    const truck = document.getElementById('cdt-manual-truck');
    if (trailer) trailer.value = '';
    if (truck) truck.value = '';
    cdtRenderManualReserveSelect();
  }

  function cdtConfirmManualReserve() {
    const dtId = document.getElementById('cdt-manual-dt-select')?.value || '';
    const trailer = cdtPlateInputValue('cdt-manual-trailer');
    const truck = cdtPlateInputValue('cdt-manual-truck');
    const dt = controleDtDts.find(x => String(x.id || x._id || '') === String(dtId));

    if (!dtId || !dt) return showToast('Selecione uma DT pendente para reservar.', 'error');
    if ((dt.status || 'Pendente') !== 'Pendente') return showToast('Essa DT não está mais pendente.', 'error');
    if (!trailer && !truck) return showToast('Informe pelo menos a placa da carreta ou do cavalo.', 'error');

    const plateLabel = [trailer ? `carreta ${trailer}` : '', truck ? `cavalo ${truck}` : ''].filter(Boolean).join(' / ');
    showConfirmModal(`Reservar a DT ${dt.code} manualmente para ${plateLabel}?`, () => cdtReserveManualDt(dtId, trailer, truck));
  }

  async function cdtReserveManualDt(dtId, trailerPlate = '', truckPlate = '') {
    const dt = controleDtDts.find(x => x.id === dtId || x._id === dtId);
    if (!dt) return showToast('DT não encontrada.', 'error');
    if ((dt.status || 'Pendente') !== 'Pendente') return showToast('Essa DT não está pendente.', 'error');

    const trailer = cdtClean(trailerPlate).toUpperCase();
    const truck = cdtClean(truckPlate).toUpperCase();
    const linkLabel = [trailer ? `Carreta ${trailer}` : '', truck ? `Cavalo ${truck}` : ''].filter(Boolean).join(' • ');

    const patch = {
      status: 'Reservada',
      reservedAt: cdtNow(),
      reservedForPlate: trailer || truck || '',
      reservedTrailerPlate: trailer,
      reservedTruckPlate: truck,
      reservedSourceId: '',
      reservedSource: 'manual',
      reservedMode: 'manual'
    };

    await cdtUpdateDt(dtId, patch, `DT ${dt.code} reservada manualmente para ${linkLabel || 'placa sem identificação'}`);
    cdtResetManualReserveForm();
    showToast(`DT ${dt.code} reservada manualmente.`, 'success');
  }

  function renderControleDt() {
    const root = document.getElementById('controle-dt-content');
    if (!root) return;
    cdtRenderSelects();

    const validDts = (controleDtDts || []).filter(dt => dt.status !== 'Cancelada');
    const pendingDts = validDts.filter(dt => (dt.status || 'Pendente') === 'Pendente');
    const reservedDts = validDts.filter(dt => dt.status === 'Reservada');
    const doneDts = validDts.filter(dt => dt.status === 'Baixada');
    const productTotals=(controleDtProducts || []).reduce((totals,p)=>{const calc=cdtProductCalc(p.id||p._id);totals.target+=calc.target;totals.scheduled+=calc.scheduled;return totals;},{target:0,scheduled:0});
    const {target,scheduled}=productTotals;

    const kpis = document.getElementById('cdt-kpis');
    if (kpis) {
      kpis.innerHTML = [
        ['Produtos', String(controleDtProducts.length), 'Programados'],
        ['DTs pendentes', String(pendingDts.length), 'Disponíveis para reserva'],
        ['DTs reservadas', String(reservedDts.length), 'Travadas para placa'],
        ['DTs baixadas', String(doneDts.length), 'Concluídas'],
        ['Paletes criados', `${cdtMoneyNum(scheduled)} / ${cdtMoneyNum(target)}`, 'Criado x programado']
      ].map(([label, value, sub]) => `
        <div class="cdt-kpi">
          <div class="cdt-kpi-label">${escapeHtml(label)}</div>
          <div class="cdt-kpi-value">${escapeHtml(value)}</div>
          <div class="text-sm cdt-muted font-bold mt-2">${escapeHtml(sub)}</div>
        </div>
      `).join('');
    }

    const vaziasBox = document.getElementById('cdt-vazias-list');
    if (vaziasBox) {
      const localFilterValues = getMultiSelectValues('cdt-vazia-local-filter');
      const vazias = cdtGetLatestRitmoVazias();
      if (!vazias.length) {
        const fallback = cdtAvailableDts(areAllFilterValues(localFilterValues) ? '' : localFilterValues)[0];
        vaziasBox.innerHTML = fallback ? `
          <div class="cdt-suggestion-card lg:col-span-2">
            <div class="flex flex-wrap items-center justify-between gap-3">
              <div>
                <div class="cdt-muted text-sm font-black uppercase tracking-wide">Sem vazia recente da Ritmo detectada</div>
                <div class="mt-2 text-lg font-black">Mas já existe DT disponível para teste:</div>
                <div class="cdt-dt-number mt-1">${escapeHtml(fallback.code)}</div>
                <div class="text-sm cdt-muted font-bold mt-1">${escapeHtml(fallback.productNameSnapshot || cdtProductName(fallback.productId))} • ${cdtMoneyNum(fallback.pallets)} pal • ${escapeHtml(fallback.local || '')}</div>
              </div>
              <span class="cdt-pill cdt-pill-wait">Aguardando Ritmo vazia</span>
            </div>
          </div>
        ` : `<div class="cdt-card-soft p-5 lg:col-span-2 text-center cdt-muted font-black">Cadastre DTs pendentes. Quando a Ritmo marcar uma carreta vazia, a sugestão aparece aqui automaticamente.</div>`;
      } else {
        vaziasBox.innerHTML = vazias.map(({ op, plate, local, ms }) => {
          const preferredLocal = localFilterValues.includes('auto') ? (local || '') : (areAllFilterValues(localFilterValues) ? '' : localFilterValues);
          const suggestion = cdtAvailableDts(preferredLocal)[0] || cdtAvailableDts('')[0];
          const dtId = suggestion?._id || suggestion?.id || '';
          const opId = op?.id || '';
          const opSrc = op?._src || '';
          return `
            <div class="cdt-suggestion-card">
              <div class="flex items-start justify-between gap-3">
                <div>
                  <div class="text-xs cdt-muted font-black uppercase tracking-wide">Carreta vazia Ritmo</div>
                  <div class="font-mono text-lg font-black mt-1">${escapeHtml(plate)}</div>
                  <div class="text-xs cdt-muted font-bold mt-1">${escapeHtml(new Date(ms).toLocaleString('pt-BR'))}${local ? ` • ${escapeHtml(local)}` : ''}</div>
                </div>
                <span class="cdt-pill cdt-pill-ok">Vazia</span>
              </div>
              ${suggestion ? `
                <div class="mt-4 cdt-card-soft p-4 ${cdtPriorityClass(suggestion.prioritySnapshot || cdtProductPriority(suggestion.productId))}">
                  <div class="text-xs cdt-muted font-black uppercase tracking-wide">DT disponível sugerida</div>
                  <div class="cdt-dt-number">${escapeHtml(suggestion.code)}</div>
                  <div class="text-sm font-black mt-1">${escapeHtml(suggestion.productNameSnapshot || cdtProductName(suggestion.productId))}</div>
                  <div class="text-sm cdt-muted font-bold mt-1">${cdtMoneyNum(suggestion.pallets)} pal • ${escapeHtml(suggestion.local || '')} • ${escapeHtml(suggestion.prioritySnapshot || cdtProductPriority(suggestion.productId))}</div>
                  <button type="button" class="cdt-btn cdt-btn-primary w-full mt-4" data-cdt-action="reserve" data-dt-id="${escapeHtml(dtId)}" data-plate="${escapeHtml(plate)}" data-op-id="${escapeHtml(opId)}" data-op-src="${escapeHtml(opSrc)}">Reservar DT para essa placa</button>
                </div>
              ` : `
                <div class="mt-4 cdt-card-soft p-4 text-center">
                  <div class="font-black text-red-700">Nenhuma DT pendente disponível</div>
                  <div class="text-sm cdt-muted font-bold mt-1">Cadastre uma DT ou altere o filtro de local.</div>
                </div>
              `}
            </div>
          `;
        }).join('');
      }
    }

    const productsTbody = document.getElementById('cdt-products-table-body');
    if (productsTbody) {
      const productRows = (controleDtProducts || [])
        .slice()
        .sort((a, b) => cdtPriorityWeight(a.priority || a.prioridade) - cdtPriorityWeight(b.priority || b.prioridade) || String(a.name || a.nome || '').localeCompare(String(b.name || b.nome || ''), 'pt-BR'));

      productsTbody.innerHTML = productRows.length ? productRows.map(p => {
        const id = p._id || p.id || '';
        const calc = cdtProductCalc(id);
        const priority = p.priority || p.prioridade || 'Normal';
        return `
          <tr class="${cdtPriorityClass(priority)}">
            <td class="p-3 font-black">${escapeHtml(p.name || p.nome || p.produto || '')}</td>
            <td class="p-3 font-bold">${escapeHtml(p.local || 'Fábrica')}</td>
            <td class="p-3 font-bold">${escapeHtml(priority)}</td>
            <td class="p-3 font-mono font-black">${cdtMoneyNum(calc.target)}</td>
            <td class="p-3 font-mono font-black">${cdtMoneyNum(calc.scheduled)}</td>
            <td class="p-3 font-mono font-black">${cdtMoneyNum(calc.pending)}</td>
            <td class="p-3">
              <div class="flex flex-wrap justify-end gap-2">
                <button type="button" class="cdt-btn cdt-btn-ghost !py-2 !px-3 text-xs" data-cdt-action="edit-product" data-product-id="${escapeHtml(id)}">Editar</button>
                <button type="button" class="cdt-btn cdt-btn-red !py-2 !px-3 text-xs" data-cdt-action="delete-product" data-product-id="${escapeHtml(id)}">Excluir</button>
              </div>
            </td>
          </tr>
        `;
      }).join('') : `<tr><td colspan="7" class="p-6 text-center cdt-muted font-black">Nenhum produto cadastrado.</td></tr>`;
    }

    const statusFilterValues = getMultiSelectValues('cdt-status-filter');
    const tbody = document.getElementById('cdt-dts-table-body');
    if (tbody) {
      const rows = (controleDtDts || [])
        .filter(dt => filterValuesMatchExact(statusFilterValues, dt.status || 'Pendente'))
        .sort((a, b) => cdtPriorityWeight(a.prioritySnapshot || cdtProductPriority(a.productId)) - cdtPriorityWeight(b.prioritySnapshot || cdtProductPriority(b.productId)) || cdtNum(b.createdAt) - cdtNum(a.createdAt));
      tbody.innerHTML = rows.length ? rows.map(dt => {
        const id = dt._id || dt.id || '';
        const status = dt.status || 'Pendente';
        return `
          <tr class="${cdtPriorityClass(dt.prioritySnapshot || cdtProductPriority(dt.productId))}">
            <td class="p-3 font-mono font-black">${escapeHtml(dt.code || '')}</td>
            <td class="p-3 font-bold">${escapeHtml(dt.productNameSnapshot || cdtProductName(dt.productId))}</td>
            <td class="p-3 font-bold">${escapeHtml(dt.local || '')}</td>
            <td class="p-3 font-mono font-black">${cdtMoneyNum(dt.pallets)}</td>
            <td class="p-3">${cdtStatusPill(status)}</td>
            <td class="p-3 text-sm font-bold cdt-muted">${escapeHtml(cdtDtLinkLabel(dt))}</td>
            <td class="p-3">
              <div class="flex flex-wrap justify-end gap-2">
                ${status === 'Reservada' ? `<button type="button" class="cdt-btn cdt-btn-ghost !py-2 !px-3 text-xs" data-cdt-action="status" data-status="Pendente" data-dt-id="${escapeHtml(id)}">Desfazer</button>` : ''}
                ${status !== 'Baixada' && status !== 'Cancelada' ? `<button type="button" class="cdt-btn cdt-btn-primary !py-2 !px-3 text-xs" data-cdt-action="status" data-status="Baixada" data-dt-id="${escapeHtml(id)}">Baixar</button>` : ''}
                ${status !== 'Cancelada' ? `<button type="button" class="cdt-btn cdt-btn-red !py-2 !px-3 text-xs" data-cdt-action="status" data-status="Cancelada" data-dt-id="${escapeHtml(id)}">Cancelar</button>` : ''}
              </div>
            </td>
          </tr>
        `;
      }).join('') : `<tr><td colspan="7" class="p-8 text-center cdt-muted font-black">Nenhuma DT encontrada.</td></tr>`;
    }

    const movements = document.getElementById('cdt-movements-list');
    if (movements) {
      const rows = (controleDtMovements || [])
        .slice()
        .sort((a,b) => cdtNum(b.createdAt) - cdtNum(a.createdAt))
        .slice(0, 30);
      movements.innerHTML = rows.length ? rows.map(m => `
        <div class="cdt-card-soft p-3 flex flex-wrap items-center justify-between gap-3">
          <div>
            <div class="font-black">${escapeHtml(m.text || '')}</div>
            <div class="text-xs cdt-muted font-bold mt-1">${escapeHtml(m.type || 'Movimento')} • ${m.createdAt ? escapeHtml(new Date(cdtNum(m.createdAt)).toLocaleString('pt-BR')) : '—'}</div>
          </div>
        </div>
      `).join('') : `<div class="cdt-card-soft p-4 text-center cdt-muted font-black">Sem movimentos ainda.</div>`;
    }
  }

  async function cdtDeleteCollectionDocs(collectionName) {
    if (!(controleDtUsingFirestore && db)) return false;
    const snap = await getDocs(collection(db, cdtCollectionPath(collectionName)));
    if (snap.empty) return true;
    let batch = writeBatch(db);
    let count = 0;
    for (const item of snap.docs) {
      batch.delete(item.ref);
      count += 1;
      if (count % 450 === 0) {
        await batch.commit();
        batch = writeBatch(db);
      }
    }
    await batch.commit();
    return true;
  }

