    try {
      if (controleDtUsingFirestore && db) {
        await cdtDeleteCollectionDocs('controle_dt_movimentos');
      }
      controleDtMovements = [];
      cdtPersistLocal();
      renderControleDt();
      showToast('Histórico do Controle de DTs limpo.', 'success');
    } catch (err) {
      console.error(err);
      showToast('Erro ao limpar histórico.', 'error');
    }
