      if(target.path!==original.path&&(await tx.get(original)).exists())throw Error('Há uma nova marcação no Pátio. Não é possível sobrescrevê-la.');
      const linkedRef=a.linkedId?doc(db,`${path}/controle_dt_dts`,a.linkedId):null,linked=linkedRef?await tx.get(linkedRef):null;
      if(linkedRef&&(!linked.exists()||api.fingerprint(linked.data())!==a.linkedAfterVersion))throw Error('A DT vinculada mudou após a importação.');
      const restored={...a.before,linhaDoTempo:appendTimelineEventToRecord(current.data(),createTimelineEvent('baldeio-sap-undo','Importação SAP estornada',`DT ${a.dt}: valores anteriores restaurados.`,Date.now(),{sapImportId:auditId}))};
      check();tx.set(original,restored);if(target.path!==original.path)tx.delete(target);
