  // DAILY MOVEMENT VIEW START
  let dailyMovementCache=null,dailyImportUnsub=null,dailyImportToken=0;
  const getDailyMovementState=(date,imported=[])=>{
    if(typeof ensureIntegratedHistory==='function')ensureIntegratedHistory();
    const path=activeDataPath(),sources=[integratedHistoryData,historicoData,patioData],lengths=sources.map(rows=>rows.length);
    const key=path+':'+date+':'+ritmoDataVersion;
    if(dailyMovementCache&&dailyMovementCache.key===key&&sources.every((rows,i)=>rows===dailyMovementCache.sources[i]&&rows.length===dailyMovementCache.lengths[i]))return {...dailyMovementCache.value,ready:integratedHistoryLoaded};
    const daily=window.HeilogDaily,start=Date.parse(date+'T00:00:00-03:00'),end=start+86400000,records=new Map();
    for(let sourceIndex=0;sourceIndex<sources.length;sourceIndex++)for(const op of sources[sourceIndex]){
      if(op.status==='Cancelado')continue;
      const mark=getOperationMarkingMs(op),finished=getTimelineMs(op.finishedTime);
      if(!(mark>=start&&mark<end))continue;
      const flow=getEwmFlow(op),loadedAt=getTimelineMs(flow.times?.[3])||getTimelineMs(op.dockExitTime||op.dockExitAtMs);
      const identity=(op.operacaoIdOriginal||op.id)+':'+mark;
      const type=getTipoOperacaoPainel(op),explicit=daily.kind(type),classified=explicit!=='Não classificado'&&explicit!=='Carregamento'?explicit:typeof isBaldeioOp==='function'&&isBaldeioOp(op)?'Baldeios':isPerfFlowVendas(op)?'Vendas':isPerfFlowCargaDescarga(op)?'Carga e descarga':typeof isPerfFlowBaldeio==='function'&&isPerfFlowBaldeio(op)?'Baldeios':explicit!=='Não classificado'?explicit:op.baldeio===true?'Baldeios':daily.kind([op.tipoOperacao,op.operacao,op.operationType].filter(Boolean).join(' '));
      const priority=typeof getStoredPrioritySnapshot==='function'?getStoredPrioritySnapshot(op):{};
      records.set(identity,{markedBaldeio:daily.markedBaldeio(op),markedBaldeioJsl:daily.markedBaldeioJsl(op),heilogMarkAt:mark,heilogTransportType:String(op.canal||op.tipoTransporte||''),heilogSegment:String(op.segmento||op.segmentacao||''),operationId:op.operacaoIdOriginal||op.id,activityId:op.linhaDoTempoId||op.timelineSessionId||op.marcacaoId||op.activityId||'',finishedAt:finished,priorityCode:priority.priorityCode||'',priorityLabel:priority.priorityLabel||'',agendaStatus:priority.operationalStatus||'',prioritySource:'HEILOG',id:op.id,identity,dt:String(op.dt||''),truck:getTruckPlate(op),trailer:getTrailerPlate(op),carrier:String(typeof getTransportadoraFromOperacao==='function'?getTransportadoraFromOperacao(op):op.transportadora||''),arrivalAt:mark,loadedAt,kind:classified,status:op.status||''});
    }
    const adapted=[...records.values()],byOperation=new Map();
    for(const row of adapted){if(!byOperation.has(row.operationId))byOperation.set(row.operationId,[]);byOperation.get(row.operationId).push(row);}
    for(const items of byOperation.values()){items.sort((a,b)=>a.arrivalAt-b.arrivalAt);for(let i=0;i<items.length-1;i++)items[i].nextMark=items[i+1].arrivalAt;}
    const value={path,records:adapted,ready:integratedHistoryLoaded};dailyMovementCache={key,sources,lengths,value};return value;
  };
  const stopDailyMovementImport=()=>{dailyImportToken++;dailyImportUnsub?.();dailyImportUnsub=null;};
  const loadDailyMovementImport=(date,onChange)=>new Promise((resolve,reject)=>{
    stopDailyMovementImport();const token=dailyImportToken,path=activeDataPath();let delivered=false,revision=0;
    dailyImportUnsub=onSnapshot(doc(db,`${path}/daily_movements`,date),async snapshot=>{
      const current=++revision;
      try{
        const meta=snapshot.exists()?snapshot.data():null;
        const chunks=meta?await Promise.all(Array.from({length:Math.min(Number(meta.chunkCount)||0,100)},(_,i)=>getDoc(doc(db,`${path}/daily_movements/${date}/batches`,meta.version+'_'+i)))):[];
        if(token!==dailyImportToken||activeDataPath()!==path||current!==revision)return;
        if(chunks.some(snap=>!snap.exists()))throw Error('O relatório ainda não está completo. Atualize a visão.');
        const data={meta,rows:chunks.flatMap(snap=>snap.data()?.rows||[])};
        if(!delivered){delivered=true;resolve(data);}else onChange?.(data);
      }catch(error){if(token!==dailyImportToken)return;if(!delivered){delivered=true;reject(error);}else showToast('Não foi possível atualizar a lista SAP.','error');}
    },error=>{if(token!==dailyImportToken)return;if(!delivered){delivered=true;reject(error);}else showToast('Não foi possível ler a comparação SAP.','error');});
  });
  const saveDailyMovementImport=async(date,rows,fileName)=>{
    if(!canManageEwm())throw Error('Seu perfil não permite importar relatórios.');
    const path=activeDataPath(),version=String(Date.now())+'_'+crypto.randomUUID(),batch=writeBatch(db),chunkCount=Math.ceil(rows.length/200);
    for(let i=0;i<chunkCount;i++)batch.set(doc(db,`${path}/daily_movements/${date}/batches`,version+'_'+i),{rows:rows.slice(i*200,(i+1)*200)});
    const actor=timelineActorSnapshot();
    batch.set(doc(db,`${path}/daily_movements`,date),{version,chunkCount,count:rows.length,fileName:String(fileName).slice(0,200),date,importedAtMs:Date.now(),importedBy:actor.usuario||actor.username||'Usuário'});
    if(activeDataPath()!==path||!canManageEwm())throw Error('A unidade ou o acesso mudou.');
    await batch.commit();
  };
  let dailyOccurrenceToken=0,dailyOccurrenceWatch={key:'',rows:[],ready:false,error:false,unsubs:[]};
  const stopDailyOccurrences=()=>{
    dailyOccurrenceToken++;
    dailyOccurrenceWatch.unsubs.forEach(unsub=>unsub());
    dailyOccurrenceWatch={key:'',rows:[],ready:false,error:false,unsubs:[]};
  };
  const watchDailyOccurrences=rows=>{
    const daily=window.HeilogDaily,path=activeDataPath(),session=dropManagerSession();
    const ids=[...new Set(rows.flatMap(row=>row.operationId?[row.operationId,row.id].filter(Boolean):[]))].sort();
    const transports=new Map();
    for(const row of rows){const normalized=daily.dt(row.dt);if(!normalized)continue;for(const value of [String(row.dt).trim(),normalized,Number(normalized)]){
      if(typeof value==='number'&&!Number.isSafeInteger(value))continue;
      transports.set(typeof value+':'+value,value);
    }}
    const dts=[...transports.values()].sort((a,b)=>String(a).localeCompare(String(b))||String(typeof a).localeCompare(typeof b));
    const key=path+'|'+session.uid+'|'+JSON.stringify([ids,dts]);
    if(dailyOccurrenceWatch.key===key)return dailyOccurrenceWatch;
    stopDailyOccurrences();const token=dailyOccurrenceToken,parts=new Map(),ready=new Set(),failed=new Set();
    const watch=dailyOccurrenceWatch={key,rows:[],ready:false,error:false,unsubs:[]},refs=[],base=collection(db,`${path}/ocorrencias`);
    for(const [field,values] of [['operacaoId',ids],['dt',dts]])for(let i=0;i<values.length;i+=10)refs.push(query(base,where(field,'in',values.slice(i,i+10))));
    if(!refs.length){watch.ready=true;return watch;}
    const update=()=>{
      if(token!==dailyOccurrenceToken||dailyOccurrenceWatch!==watch||activeDataPath()!==path)return;
      const merged=new Map();for(const items of parts.values())for(const item of items)merged.set(item.id,item);
      watch.rows=[...merged.values()];watch.ready=ready.size===refs.length;watch.error=failed.size>0;
      if(activeTab==='movimento-dia')debouncedRender();
    };
    refs.forEach((ref,index)=>watch.unsubs.push(onSnapshot(ref,snap=>{
      if(token!==dailyOccurrenceToken)return;
      parts.set(index,snap.docs.map(doc=>({...doc.data(),id:doc.id})));ready.add(index);failed.delete(index);update();
    },error=>{if(token!==dailyOccurrenceToken)return;console.warn('Movimento do dia: falha ao consultar ocorrências.',error);failed.add(index);ready.delete(index);update();})));
    return watch;
  };
  if(window.HeilogDaily&&document.getElementById('baldeio-daily')){
    window.HeilogDailyUI=window.HeilogDaily.createUI({element:document.getElementById('baldeio-daily'),getState:getDailyMovementState,loadImport:loadDailyMovementImport,saveImport:saveDailyMovementImport,stopImport:stopDailyMovementImport,watchOccurrences:watchDailyOccurrences,stopOccurrences:stopDailyOccurrences,canImport:canManageEwm,toast:showToast,isVisible:()=>activeTab==='movimento-dia'});
  }
