  async function deleteBaldeioMark(docId, src) {
    if (!db || !docId || !src) return;
    const col = (src === 'historico') ? 'historico' : 'patio';

    try {
      await deleteDoc(doc(db, `${activeDataPath()}/${col}`, docId));
      showToast("Marcação excluída.", "success");
      if (activeTab === 'baldeios') setTimeout(renderBaldeiosRitmo, 200);
    } catch (err) {
      console.error("Erro ao excluir marcação:", err);
      showToast("Erro ao excluir (permissão/regras).", "error");
    }
  }




  // ============================================================
  // ✅ CONTROLE RITMO — placa a placa (histórico + novos)
  // ============================================================
  const dayKeyLocal = (ms) => {
    const d = new Date(ms);
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${dd}`;
  };

  const dayLabelPtLocal = (ms) => {
    const d = new Date(ms);
    return d.toLocaleDateString('pt-BR', { weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit' });
  };

  const avgDelta = (times) => {
    if (!Array.isArray(times) || times.length < 2) return null;
    let sum = 0, cnt = 0;
    for (let i = 1; i < times.length; i++) {
      const d = times[i] - times[i-1];
      if (Number.isFinite(d) && d >= 0) { sum += d; cnt++; }
    }
    return cnt ? (sum / cnt) : null;
  };

  function buildRitmoIndex(startMs, endMs, mode, searchCompact, onlyBaldeio) {
    const map = new Map(); // plateCompact -> { plateRaw, days: Map<dayKey, entries[]> }

    const toEntries = (ops, src) => ops.map(op => {
      const ts = op.registrationTime || op.timestamp || op.createdAt || op.created_at;
      return { ...op, _src: src, _rt: toMs(ts) };
    });

    const allOps = [...toEntries(patioData || [], 'patio'), ...toEntries(historicoData || [], 'historico')]
      .filter(op => op._rt && op._rt >= startMs && op._rt < endMs);

    allOps.forEach(op => {
      if (!isRitmoOp(op)) return;
      if (onlyBaldeio && !isBaldeioOp(op)) return;

      const plateRaw = plateKey(op, mode);
      if (!plateRaw) return;

      const plateCompact = String(plateRaw).toUpperCase().replace(/[^A-Z0-9]/g, '');

      if (searchCompact) {
        const dtCompact = String(op.dt || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
        if (!plateCompact.includes(searchCompact) && !dtCompact.includes(searchCompact)) return;
      }

      const dkey = dayKeyLocal(op._rt);
      const entry = { ms: op._rt, id: op.id || '', src: op._src, dt: op.dt || '' };

      if (!map.has(plateCompact)) map.set(plateCompact, { plateRaw: String(plateRaw), days: new Map() });
      const item = map.get(plateCompact);

      if (!item.days.has(dkey)) item.days.set(dkey, []);
      item.days.get(dkey).push(entry);
    });

    // sort day entries
    map.forEach(item => {
      item.days.forEach((arr, k) => arr.sort((a,b)=>a.ms-b.ms));
    });

    return map;
  }

  function renderRitmoDetailForPlate(plateCompact) {
    const detail = document.getElementById('ritmo-detail');
    const clearBtn = document.getElementById('ritmo-clear-selected');
    if (!detail) return;

    const item = ritmoCacheDetails.get(plateCompact);
    if (!item) {
      detail.innerHTML = `<div class="p-4 rounded-lg border border-white/10 bg-black/10">Selecione uma placa válida.</div>`;
      if (clearBtn) clearBtn.classList.add('hidden');
      return;
    }

    if (clearBtn) clearBtn.classList.remove('hidden');

    const days = Array.from(item.days.entries())
      .map(([k, entries]) => ({ k, entries, first: entries[0]?.ms || 0 }))
      .sort((a,b)=>b.first-a.first); // dia mais recente primeiro

    const dayCards = days.map(d => {
      const times = d.entries.map(e => e.ms);
      const avg = avgDelta(times);
      const total = d.entries.length;

      // chips com delete
      const chips = d.entries.map(e => `
        <span class="inline-flex items-center gap-2 px-2 py-1 rounded-md bg-gray-700/60 border border-gray-600/60 text-sm font-mono">
          <span>${escapeHtml(fmtHHMM(e.ms))}</span>
          ${(e.id && e.src) ? `
            <button type="button"
              data-action="delete-baldeio"
              data-id="${escapeHtml(e.id)}"
              data-src="${escapeHtml(e.src)}"
              data-ms="${String(e.ms)}"
              class="text-red-300 hover:text-red-200 hover:bg-red-500/10 rounded px-1"
              title="Excluir esta marcação"><svg class="w-4 h-4 pointer-events-none" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <polyline points="3 6 5 6 21 6"></polyline>
                <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"></path>
                <path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                <line x1="10" y1="11" x2="10" y2="17"></line>
                <line x1="14" y1="11" x2="14" y2="17"></line>
              </svg></button>
          ` : ``}
        </span>
      `).join('');

      // deltas
      const deltas = [];
      for (let i=1;i<times.length;i++) deltas.push(fmtDelta(times[i]-times[i-1]));
      const deltaTxt = deltas.length ? deltas.join(' | ') : '—';

      return `
        <div class="p-4 rounded-lg border border-white/10 bg-black/10 mb-3">
          <div class="flex items-center justify-between gap-3">
            <div class="font-semibold">${escapeHtml(dayLabelPtLocal(d.first))}</div>
            <div class="text-xs text-gray-400">
              <span class="font-bold text-gray-200">${total}</span> marcações
              ${avg ? ` • média: <span class="font-mono">${escapeHtml(fmtDelta(avg))}</span>` : ``}
            </div>
          </div>

          <div class="mt-3 flex flex-wrap gap-2">
            ${chips || `<span class="text-gray-500">—</span>`}
          </div>

          <div class="mt-3 text-xs text-gray-400">
            <span class="font-semibold">Intervalos:</span> <span class="font-mono">${escapeHtml(deltaTxt)}</span>
          </div>
        </div>
      `;
    }).join('');

    detail.innerHTML = `
      <div class="mb-4 p-3 rounded-lg border border-white/10 bg-black/10">
        <div class="text-sm text-gray-200"><span class="text-gray-400">Placa:</span> <span class="font-mono font-bold">${escapeHtml(item.plateRaw)}</span></div>
        <div class="text-xs text-gray-400 mt-1">Dias: ${item.days.size} • Marcações: ${item.totalMarks}</div>
      </div>
      ${dayCards || `<div class="p-4 rounded-lg border border-white/10 bg-black/10">Sem dados.</div>`}
    `;
  }

  function renderRitmoPlacaControl(forceRebuild = false) {
    const tbody = document.getElementById('ritmo-table-body');
    if (!tbody) return;

    const startEl = document.getElementById('ritmo-start');
    const endEl = document.getElementById('ritmo-end');
    const mode = document.getElementById('ritmo-plate-mode')?.value || 'carreta';
    const onlyBaldeio = !!document.getElementById('ritmo-only-baldeio')?.checked;
    const searchRaw = (document.getElementById('ritmo-search')?.value || '').trim().toUpperCase();
    const searchCompact = searchRaw.replace(/[^A-Z0-9]/g,'');

    const startDate = parseDateInputLocal(startEl?.value);
    const endDate = parseDateInputLocal(endEl?.value);

    const startMs = startDate ? startOfDay(startDate).getTime() : startOfDay(new Date(Date.now() - 30*24*3600*1000)).getTime();
    const endMs = endDate ? endExclusiveOfLocalDateInput(endEl.value) : (startOfDay(new Date()).getTime() + 24*3600*1000);

    const cacheKey = `${ritmoDataVersion}|${startMs}|${endMs}|${mode}|${searchCompact}|${onlyBaldeio ? 1 : 0}`;

    if (forceRebuild || cacheKey !== ritmoCacheKey) {
      ritmoCacheKey = cacheKey;
      ritmoPage = 1;
      ritmoCacheRows = [];
      ritmoCacheDetails = new Map();

      const idx = buildRitmoIndex(startMs, endMs, mode, searchCompact, onlyBaldeio);

      // build rows
      const rows = [];
      idx.forEach((item, plateCompact) => {
        let totalMarks = 0;
        let lastMs = 0;

        item.days.forEach(arr => {
          totalMarks += arr.length;
          const last = arr[arr.length-1]?.ms || 0;
          if (last > lastMs) lastMs = last;
        });

        // avg delta across all times (flatten)
        const allTimes = [];
        item.days.forEach(arr => arr.forEach(e => allTimes.push(e.ms)));
        allTimes.sort((a,b)=>a-b);
        const avg = avgDelta(allTimes);

        const row = {
          plateCompact,
          plateRaw: item.plateRaw,
          days: item.days,
          totalMarks,
          lastMs,
          avgMs: avg
        };
        rows.push(row);

        // store for detail panel
        ritmoCacheDetails.set(plateCompact, { plateRaw: item.plateRaw, days: item.days, totalMarks });
      });

      rows.sort((a,b)=> (b.totalMarks - a.totalMarks) || (b.lastMs - a.lastMs));
      ritmoCacheRows = rows;

      // reset selected plate if it doesn't exist anymore
      if (ritmoSelectedPlate && !ritmoCacheDetails.has(ritmoSelectedPlate)) ritmoSelectedPlate = null;
    }

    const info = document.getElementById('ritmo-summary-info');
    if (info) info.textContent = `Placas encontradas: ${ritmoCacheRows.length}`;

    const total = ritmoCacheRows.length;
    if (!total) {
      tbody.innerHTML = `<tr><td colspan="6" class="p-8 text-center text-gray-400">Nenhum registro da Ritmo encontrado no período (se marcou “Somente Baldeio”, verifique se o Tipo contém BALDEIO).</td></tr>`;
      const pi = document.getElementById('ritmo-pagination-info');
      const btn = document.getElementById('ritmo-load-more');
      if (pi) pi.textContent = '';
      if (btn) btn.classList.add('hidden');
      const clearBtn = document.getElementById('ritmo-clear-selected');
      if (clearBtn) clearBtn.classList.add('hidden');
      document.getElementById('ritmo-detail').innerHTML = `<div class="p-4 rounded-lg border border-white/10 bg-black/10">Sem dados para detalhar.</div>`;
      return;
    }

    const max = Math.min(total, ritmoPage * RITMO_PAGE_SIZE);
    const visible = ritmoCacheRows.slice(0, max);

    const pi = document.getElementById('ritmo-pagination-info');
    const btn = document.getElementById('ritmo-load-more');
    if (pi) pi.textContent = `Mostrando ${max} de ${total}`;
    if (btn) btn.classList.toggle('hidden', max >= total);

    tbody.innerHTML = visible.map(r => {
      const lastTxt = r.lastMs ? new Date(r.lastMs).toLocaleString('pt-BR') : '—';
      const avgTxt = r.avgMs ? fmtDelta(r.avgMs) : '—';
      const isSel = (ritmoSelectedPlate === r.plateCompact);

      return `
        <tr class="border-b border-gray-700 hover:bg-gray-700/40 ${isSel ? 'bg-blue-500/10' : ''}">
          <td class="p-4 font-mono text-sm">${escapeHtml(r.plateRaw)}</td>
          <td class="p-4 text-sm font-bold">${r.days.size}</td>
          <td class="p-4 text-sm font-bold">${r.totalMarks}</td>
          <td class="p-4 text-sm">${escapeHtml(lastTxt)}</td>
          <td class="p-4 font-mono text-sm">${escapeHtml(avgTxt)}</td>
          <td class="p-4">
            <button type="button" data-action="ritmo-view" data-plate="${escapeHtml(r.plateCompact)}"
              class="bg-emerald-900 hover:bg-emerald-800 text-white font-bold py-2 px-3 rounded-lg text-sm">
              Ver
            </button>
          </td>
        </tr>
      `;
    }).join('');

    // render detail if selected
    if (ritmoSelectedPlate) renderRitmoDetailForPlate(ritmoSelectedPlate);
  }



  // ============================================================
  // ✅ DASHBOARD RITMO (totais + baldeio)
  // ============================================================
  const isoDate = (d) => {
    const x = new Date(d);
    const y = x.getFullYear();
    const m = String(x.getMonth() + 1).padStart(2,'0');
    const dd = String(x.getDate()).padStart(2,'0');
    return `${y}-${m}-${dd}`;
  };

  const fmtDatePt = (ms) => new Date(ms).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });

  const makeCsv = (headers, rows) => {
    const esc = (v) => `"${String(v ?? '').replace(/"/g,'""')}"`;
    return headers.join(',') + '\n' + rows.map(r => r.map(esc).join(',')).join('\n');
  };

  function exportRitmoDashboardCsv() {
    const rep = ritmoDashLastExport;
    if (!rep || !Array.isArray(rep.rows) || !rep.rows.length) {
      showToast("Sem dados para exportar (Dashboard Ritmo).", "info");
      return;
    }

    const csv = makeCsv(rep.headers, rep.rows);

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `dashboard_ritmo_${rep.range || 'periodo'}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    showToast("CSV exportado.", "success");
  }

  function renderRitmoDashboard() {
    const kpiWrap = document.getElementById('ritmo-dash-kpis');
    const dailyCanvas = document.getElementById('ritmo-dash-daily-chart');
    const topCanvas = document.getElementById('ritmo-dash-top-plates-chart');
    const heatCanvas = document.getElementById('ritmo-dash-heatmap-chart');
    if (!kpiWrap || !dailyCanvas || !topCanvas || !heatCanvas) return;

    const startEl = document.getElementById('ritmo-dash-start');
    const endEl = document.getElementById('ritmo-dash-end');
    const mode = document.getElementById('ritmo-dash-plate-mode')?.value || 'carreta';
    const onlyBaldeio = !!document.getElementById('ritmo-dash-only-baldeio')?.checked;

    const startDate = parseDateInputLocal(startEl?.value) || new Date(Date.now() - 30*24*3600*1000);
    const endDate = parseDateInputLocal(endEl?.value) || new Date();

    const startMs = startOfDay(startDate).getTime();
    const endMs = endEl?.value ? endExclusiveOfLocalDateInput(endEl.value) : (startOfDay(endDate).getTime() + 24*3600*1000);

    const toEntries = (ops, src) => (ops || []).map(op => {
      const ts = op.registrationTime || op.timestamp || op.createdAt || op.created_at;
      return { ...op, _src: src, _rt: toMs(ts) };
    });

    const allOps = [...toEntries(patioData, 'patio'), ...toEntries(historicoData, 'historico')]
      .filter(op => op._rt && op._rt >= startMs && op._rt < endMs);

    const ritmoOps = allOps.filter(op => isRitmoOp(op));
    const ritmoBaldeioOps = ritmoOps.filter(op => isBaldeioOp(op));
    const used = onlyBaldeio ? ritmoBaldeioOps : ritmoOps;

    const plateCount = {};
    used.forEach(op => {
      const p = String(plateKey(op, mode) || '').toUpperCase().replace(/[^A-Z0-9]/g,'');
      if (!p) return;
      plateCount[p] = (plateCount[p] || 0) + 1;
    });

    const uniquePlates = Object.keys(plateCount).length;
    const repeatPlates = Object.values(plateCount).filter(x => x >= 2).length;

    let sumInterval = 0, cntInterval = 0;
    Object.keys(plateCount).forEach(p => {
      const times = used
        .filter(op => String(plateKey(op, mode) || '').toUpperCase().replace(/[^A-Z0-9]/g,'') === p)
        .map(op => op._rt)
        .filter(Boolean)
        .sort((a,b)=>a-b);

      for (let i=1;i<times.length;i++) {
        const d = times[i]-times[i-1];
        if (Number.isFinite(d) && d >= 0) { sumInterval += d; cntInterval += 1; }
      }
    });
    const avgIntervalMs = cntInterval ? (sumInterval / cntInterval) : null;

    const totalRitmo = ritmoOps.length;
    const totalBaldeio = ritmoBaldeioOps.length;
    const baldeioShare = totalRitmo ? Math.round((totalBaldeio/totalRitmo)*100) : 0;

    const kpi = (title, value, sub='') => `
      <div class="kpi-card-sm rounded-lg p-4">
        <p class="text-xs text-gray-400">${title}</p>
        <p class="text-2xl font-bold mt-1">${value}</p>
        ${sub ? `<p class="text-xs text-gray-500 mt-1">${sub}</p>` : ``}
      </div>
    `;

    kpiWrap.innerHTML = `
      ${kpi(onlyBaldeio ? 'Baldeios (Ritmo)' : 'Marcações (Ritmo)', used.length, `${fmtDatePt(startMs)} → ${fmtDatePt(endMs-1)}`)}
      ${kpi('Placas únicas', uniquePlates, repeatPlates ? `${repeatPlates} com repetição` : '—')}
      ${kpi('Ritmo total', totalRitmo, `Baldeio: ${totalBaldeio} (${baldeioShare}%)`)}
      ${kpi('Média entre marcações', avgIntervalMs ? fmtDelta(avgIntervalMs) : '—', cntInterval ? `${cntInterval} intervalos` : '—')}
    `;

    // Daily series
    const days = [];
    for (let cur = new Date(startMs); cur.getTime() < endMs; cur.setDate(cur.getDate()+1)) {
      days.push(new Date(cur));
    }
    const keys = days.map(d => isoDate(d));
    const labels = days.map(d => d.toLocaleDateString('pt-BR', { day:'2-digit', month:'2-digit'}));

    const dailyTotal = {}, dailyBaldeio = {};
    keys.forEach(k => { dailyTotal[k]=0; dailyBaldeio[k]=0; });

    ritmoOps.forEach(op => {
      const k = isoDate(op._rt);
      if (k in dailyTotal) dailyTotal[k] += 1;
    });
    ritmoBaldeioOps.forEach(op => {
      const k = isoDate(op._rt);
      if (k in dailyBaldeio) dailyBaldeio[k] += 1;
    });

    const seriesTotal = keys.map(k => dailyTotal[k] || 0);
    const seriesBald = keys.map(k => dailyBaldeio[k] || 0);

    // Daily chart
    ritmoDashDailyChart = safeDestroyChart(ritmoDashDailyChart);
    ritmoDashDailyChart = new Chart(dailyCanvas.getContext('2d'), {
      type: 'bar',
      data: {
        labels,
        datasets: [
          { label: 'Ritmo (total)', data: seriesTotal, backgroundColor: 'rgba(59,130,246,0.50)', borderColor: 'rgba(59,130,246,0.95)', borderWidth: 1, borderRadius: 6 },
          { label: 'Baldeio', data: seriesBald, backgroundColor: 'rgba(16,185,129,0.45)', borderColor: 'rgba(16,185,129,0.90)', borderWidth: 1, borderRadius: 6 }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { labels: { color: '#d1d5db' } } },
        scales: {
          y: { beginAtZero: true, ticks: { color: '#d1d5db', precision: 0 }, grid: { color: 'rgba(255,255,255,0.08)' } },
          x: { ticks: { color: '#d1d5db' }, grid: { display: false } }
        }
      }
    });

    // Top plates
    const top = Object.entries(plateCount).sort((a,b)=>b[1]-a[1]).slice(0, 12);
    const topLabels = top.map(x => x[0]);
    const topValues = top.map(x => x[1]);

    ritmoDashTopPlatesChart = safeDestroyChart(ritmoDashTopPlatesChart);
    ritmoDashTopPlatesChart = new Chart(topCanvas.getContext('2d'), {
      type: 'bar',
      data: { labels: topLabels, datasets: [{ label: 'Marcações', data: topValues, backgroundColor: 'rgba(245,158,11,0.55)', borderColor: 'rgba(245,158,11,0.95)', borderWidth: 1, borderRadius: 6 }] },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        plugins: { legend: { display: false } },
        scales: {
          x: { beginAtZero: true, ticks: { color: '#d1d5db', precision: 0 }, grid: { color: 'rgba(255,255,255,0.08)' } },
          y: { ticks: { color: '#d1d5db' }, grid: { display: false } }
        }
      }
    });

    // Heatmap (last 7 days in range)
    const startHeatMs = Math.max(startMs, endMs - 7*24*3600*1000);
    const heatOps = used.filter(op => op._rt && op._rt >= startHeatMs && op._rt < endMs);

    const heatDays = [];
    for (let cur = new Date(startHeatMs); cur.getTime() < endMs; cur.setDate(cur.getDate()+1)) {
      heatDays.push(new Date(cur));
      if (heatDays.length >= 7) break;
    }
    const heatKeys = heatDays.map(d => isoDate(d));
    const heatLabels = heatDays.map(d => d.toLocaleDateString('pt-BR', { weekday:'short', day:'2-digit', month:'2-digit' }));

    const matrix = Array.from({ length: heatDays.length }, () => Array.from({ length: 24 }, () => 0));
    heatOps.forEach(op => {
      const k = isoDate(op._rt);
      const dayIdx = heatKeys.indexOf(k);
      if (dayIdx === -1) return;
      const hour = new Date(op._rt).getHours();
      matrix[dayIdx][hour] += 1;
    });

    const points = [];
    for (let y=0; y<heatDays.length; y++) for (let x=0; x<24; x++) points.push({ x, y, v: matrix[y][x] });
    const maxV = points.reduce((m,p)=>Math.max(m,p.v),0);

    ritmoDashHeatmapChart = safeDestroyChart(ritmoDashHeatmapChart);
    ritmoDashHeatmapChart = new Chart(heatCanvas.getContext('2d'), {
      type: 'matrix',
      data: {
        datasets: [{
          label: 'Marcações',
          data: points,
          backgroundColor: (ctx) => {
            const v = ctx.raw?.v ?? 0;
            if (!v) return 'rgba(255,255,255,0.03)';
            const a = Math.min(0.85, 0.12 + (maxV ? (v / maxV) * 0.75 : 0.2));
            return `rgba(59, 130, 246, ${a})`;
          },
          borderColor: 'rgba(17,24,39,0.35)',
          borderWidth: 1,
          width: ({ chart }) => (chart.chartArea || {}).width / 24 - 2,
          height: ({ chart }) => (chart.chartArea || {}).height / Math.max(1, heatDays.length) - 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              title: (items) => {
                const r = items?.[0]?.raw;
                if (!r) return '';
                const day = heatLabels[r.y] || '';
                const h = String(r.x).padStart(2,'0');
                return `${day} — ${h}:00`;
              },
              label: (item) => ` ${item.raw?.v ?? 0} marcação(ões)`
            }
          }
        },
        scales: {
          x: {
            type: 'linear',
            position: 'bottom',
            min: 0,
            max: 23,
            ticks: { stepSize: 1, color: '#d1d5db', callback: (v) => (v % 2 === 0 ? String(v).padStart(2,'0') : '') },
            grid: { color: 'rgba(255,255,255,0.06)' }
          },
          y: {
            type: 'linear',
            min: 0,
            max: Math.max(0, heatDays.length - 1),
            ticks: { stepSize: 1, color: '#d1d5db', callback: (v) => heatLabels[v] || '' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          }
        }
      }
    });

    // Export rows (daily)
    const exportRows = keys.map((k, idx) => [k, labels[idx], dailyTotal[k] || 0, dailyBaldeio[k] || 0]);
    ritmoDashLastExport = {
      headers: ['DataISO','Data','RitmoTotal','RitmoBaldeio'],
      rows: exportRows,
      range: `${isoDate(startMs)}_${isoDate(endMs-1)}`
    };
  }



  // ==============================
  // AMBIENTE PANDORA — CONTROLE DE NF
  // ==============================
  // Coleção antiga mantida como legado para migração/consulta.
  const PANDORA_NF_COLLECTION = 'pandora_nfs';
  // Nova separação para reduzir leituras: operação ativa x arquivo.
  const PANDORA_ACTIVE_COLLECTION = 'pandora_ativo';
  const PANDORA_ARCHIVE_COLLECTION = 'pandora_arquivo';
  const PANDORA_HISTORY_COLLECTION = 'pandora_historico';
  const PANDORA_LOCAL_KEY = 'heilog_pandora_nfs_v1';
  const PANDORA_HISTORY_LOCAL_KEY = 'heilog_pandora_history_v1';
  const PANDORA_UNDO_LOCAL_KEY = 'heilog_pandora_undo_v1';
  const PANDORA_IMPORT_META_KEY = 'heilog_pandora_import_meta_v1';
  const PANDORA_CLIENTE_BASE_LOCAL_KEY = 'heilog_pandora_clientes_base_v1';
  // Visibilidade operacional: nas listas do Pandora, mostrar automaticamente apenas NFs pendentes acima de 30 dias.
  // As demais continuam consultáveis pela chave de acesso, sem precisar carregar o banco inteiro.
  const PANDORA_VISIBLE_MIN_AGE_DAYS = 30;
  const PANDORA_OLD_NFS_LIVE_LIMIT = 500;

  const PANDORA_AREAS = ['Transportes', 'Warehouse', 'Fiscal', 'Customer Service', 'Planejamento', 'Portaria', 'Operação', 'Inbound', 'Outbound', 'CIM', 'CD', 'INSIDE', 'ATIVOS COMERCIAIS', 'RPM', 'MARKETING', 'QUALIDADE', 'MANUTENÇÃO', 'UTILIDADES', 'PROJETOS', 'PROCESSO', 'SHE'];
  const PANDORA_STATUS = ['Em andamento', 'Aguardando área', 'Aguardando documento', 'Liberação de entrada', 'Com problema', 'Escriturado', 'Cancelada'];
  const PANDORA_TIPOS = ['Carregamento', 'Descarga', 'Transferência', 'Insumos', 'Baldeio', 'Venda', 'Retorno', 'Outro'];
  // Pandora Jacareí: somente notas dos centros configurados abaixo aparecem no ambiente.
  // Se futuramente o centro de Jacareí mudar, basta ajustar esta lista.
  const PANDORA_SITE_ATIVO = 'Jacareí';
  const PANDORA_JACAREI_CENTROS = ['0335', '0276'];

  const pandoraDocKey = (item = {}) => item._docId || item.id || item.localId || '';
  const pandoraCollection = (name) => collection(db, `${activeDataPath()}/${name}`);
  const pandoraDocRef = (name, id) => doc(db, `${activeDataPath()}/${name}`, id);
  const pandoraNow = () => new Date().toISOString();
  const pandoraMs = () => Date.now();
  const pandoraLocalId = (prefix = 'PD') => `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const pandoraNorm = (value = '') => String(value ?? '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const pandoraStatusClass = (status = '') => `pandora-status-pill pandora-status-${pandoraNorm(status).toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '')}`;
  const pandoraDigits = (value = '') => String(value ?? '').replace(/\D/g, '');
  const pandoraChaveNorm = (value = '') => pandoraDigits(value).replace(/^0+/, '') || pandoraDigits(value);
  function pandoraExtractNfeFromChave(chave = '') {
    const digits = pandoraDigits(chave);
    if (digits.length !== 44) return { nf: '', serie: '', modelo: '', anoMes: '' };
    const serie = digits.slice(22, 25).replace(/^0+/, '') || '0';
    const nf = digits.slice(25, 34).replace(/^0+/, '') || '0';
    return {
      uf: digits.slice(0, 2),
      anoMes: digits.slice(2, 6),
      cnpjEmitente: digits.slice(6, 20),
      modelo: digits.slice(20, 22),
      serie,
      nf,
      tipoEmissao: digits.slice(34, 35),
      codigoNf: digits.slice(35, 43),
      digitoVerificador: digits.slice(43, 44)
    };
  }

  function pandoraCompleteNfSerieFromChave(item = {}) {
    const parts = pandoraExtractNfeFromChave(item.chave || item.chaveNorm || '');
    if (!parts.nf && !parts.serie) return item || {};
    return {
      ...item,
      nf: item.nf || parts.nf || '',
      serie: item.serie || parts.serie || '',
      modeloNfe: item.modeloNfe || parts.modelo || '',
      anoMesNfe: item.anoMesNfe || parts.anoMes || ''
    };
  }

  function pandoraAutofillNfSerieFromChave(chave = '', opts = {}) {
    const parts = pandoraExtractNfeFromChave(chave);
    if (!parts.nf && !parts.serie) return parts;
    const overwrite = !!opts.overwrite;
    const nfEl = document.getElementById('pd-nf');
    const serieEl = document.getElementById('pd-serie');
    if (nfEl && (overwrite || !String(nfEl.value || '').trim())) nfEl.value = parts.nf || '';
    if (serieEl && (overwrite || !String(serieEl.value || '').trim())) serieEl.value = parts.serie || '';
    return parts;
  }
  const pandoraSheetKey = (value = '') => pandoraNorm(value).replace(/[^A-Z0-9]/g, '');
  function pandoraNormalizeStatusName(status = '') {
    const raw = String(status || '').trim();
    const norm = pandoraNorm(raw);
    if (['ENCERRADA', 'ENCERRADO', 'ESCRITURADA', 'ESCRITURADO'].includes(norm)) return 'Escriturado';
    return raw || 'Em andamento';
  }
  const pandoraDefaultStatus = (item = {}) => pandoraNormalizeStatusName(item.status || 'Em andamento');
  const pandoraIsEscriturado = (status = '') => pandoraNormalizeStatusName(status) === 'Escriturado';
  const pandoraIsArquivado = (status = '') => {
    const normalized = pandoraNormalizeStatusName(status);
    // NF finalizada no Pandora = status Escriturado. Cancelada também sai da operação ativa.
    return normalized === 'Escriturado' || normalized === 'Cancelada';
  };
  const pandoraIsPendente = (item = {}) => {
    const status = pandoraDefaultStatus(item);
    return !pandoraIsArquivado(status);
  };
  const pandoraCollectionNameForItem = (item = {}) => pandoraIsArquivado(item.status) ? PANDORA_ARCHIVE_COLLECTION : PANDORA_ACTIVE_COLLECTION;
  const pandoraOperationalCollections = () => [PANDORA_ACTIVE_COLLECTION, PANDORA_ARCHIVE_COLLECTION, PANDORA_NF_COLLECTION];
  const pandoraCollectionLabel = (name = '') => {
    if (name === PANDORA_ACTIVE_COLLECTION) return 'ativo';
    if (name === PANDORA_ARCHIVE_COLLECTION) return 'arquivo';
    if (name === PANDORA_NF_COLLECTION) return 'legado';
    return name || 'desconhecido';
  };

  function pandoraWithSource(item = {}, collectionName = '') {
    return { ...(item || {}), _sourceCollection: collectionName || item._sourceCollection || '' };
  }

  function pandoraDedupRows(rows = []) {
    const map = new Map();
    (rows || []).forEach(raw => {
      if (!raw) return;
      const item = pandoraCompleteNfSerieFromChave(raw);
      const key = pandoraDocKey(item) || (item.chaveNorm ? `CH_${item.chaveNorm}` : '') || pandoraChaveNorm(item.chave || '');
      if (!key) return;
      const current = map.get(key);
      const currentScore = current ? (current.updatedAtMs || current.importedAtMs || current.createdAtMs || 0) : -1;
      const nextScore = item.updatedAtMs || item.importedAtMs || item.createdAtMs || 0;
      if (!current || nextScore >= currentScore) map.set(key, item);
    });
    return Array.from(map.values());
  }

  async function pandoraGetDocFromCollection(collectionName, docId) {
    if (!db || !docId || pandoraUsingLocalFallback) return null;
    const snap = await getDoc(pandoraDocRef(collectionName, docId));
    if (!snap.exists()) return null;
    return pandoraWithSource(pandoraCompleteNfSerieFromChave({ ...snap.data(), id: snap.id, _docId: snap.id }), collectionName);
  }

  async function pandoraGetByDocIdFromFirestore(docId = '') {
    if (!db || !docId || pandoraUsingLocalFallback) return null;
    for (const collectionName of pandoraOperationalCollections()) {
      const item = await pandoraGetDocFromCollection(collectionName, docId);
      if (item) return item;
    }
    return null;
  }

  async function pandoraGetAllOperationalRowsFromFirestore() {
    if (!db || pandoraUsingLocalFallback) return [];
    const allRows = [];
    for (const collectionName of pandoraOperationalCollections()) {
      try {
        const snap = await getDocs(pandoraCollection(collectionName));
        snap.docs.forEach(d => allRows.push(pandoraWithSource({ ...d.data(), id: d.id, _docId: d.id }, collectionName)));
      } catch (err) {
        console.warn(`Pandora não conseguiu ler a coleção ${collectionName}:`, err);
      }
    }
    return pandoraDedupRows(allRows);
  }

  async function pandoraSaveItemRouted(item = {}, opts = {}) {
    if (!db || pandoraUsingLocalFallback) return null;
    const docId = item._docId || item.id || (item.chaveNorm ? `CH_${item.chaveNorm}` : pandoraLocalId('PDNF'));
    const targetCollection = pandoraCollectionNameForItem(item);
    const payload = pandoraEnsureIndexFields({ ...(item || {}), id: docId, _docId: docId });
    delete payload._sourceCollection;
    await setDoc(pandoraDocRef(targetCollection, docId), payload, { merge: opts.merge !== false });
    // Remove duplicidade nas outras coleções, inclusive legado.
    await Promise.all(pandoraOperationalCollections()
      .filter(name => name !== targetCollection)
      .map(async (name) => {
        try { await deleteDoc(pandoraDocRef(name, docId)); } catch (_) {}
      }));
    return pandoraWithSource({ ...payload, id: docId, _docId: docId }, targetCollection);
  }

  async function pandoraPatchItemRouted(existing = {}, patch = {}) {
    if (!db || !existing || pandoraUsingLocalFallback) return null;
    const docId = existing._docId || existing.id || (existing.chaveNorm ? `CH_${existing.chaveNorm}` : '');
    if (!docId) return null;
    const after = pandoraEnsureIndexFields({ ...existing, ...patch, id: docId, _docId: docId });
    const targetCollection = pandoraCollectionNameForItem(after);
    const currentCollection = existing._sourceCollection || '';
    if (currentCollection && currentCollection === targetCollection && currentCollection !== PANDORA_NF_COLLECTION) {
      await updateDoc(pandoraDocRef(targetCollection, docId), patch);
      return pandoraWithSource(after, targetCollection);
    }
    return await pandoraSaveItemRouted(after, { merge: true });
  }

  async function pandoraDeleteItemEverywhere(item = {}) {
    if (!db || pandoraUsingLocalFallback) return;
    const docId = item._docId || item.id || (item.chaveNorm ? `CH_${item.chaveNorm}` : '');
    if (!docId) return;
    await Promise.all(pandoraOperationalCollections().map(async (name) => {
      try { await deleteDoc(pandoraDocRef(name, docId)); } catch (_) {}
    }));
  }

  function pandoraBatchRouteSet(batch, docId = '', payload = {}, statusSource = {}, opts = {}) {
    const sourceForRoute = pandoraEnsureIndexFields({ ...(statusSource || {}), ...(payload || {}) });
    const targetCollection = pandoraCollectionNameForItem(sourceForRoute);
    const indexedPayload = { ...(payload || {}) };
    if (sourceForRoute.emissaoMs && !indexedPayload.emissaoMs) {
      indexedPayload.emissaoMs = sourceForRoute.emissaoMs;
      indexedPayload.emissaoDiaRef = sourceForRoute.emissaoDiaRef || '';
    }
    if (sourceForRoute.sitePandora && !indexedPayload.sitePandora) indexedPayload.sitePandora = sourceForRoute.sitePandora;
    batch.set(pandoraDocRef(targetCollection, docId), indexedPayload, { merge: opts.merge !== false });
    pandoraOperationalCollections().filter(name => name !== targetCollection).forEach(name => {
      batch.delete(pandoraDocRef(name, docId));
    });
    return targetCollection;
  }

  function pandoraMergeLoadedRows(rows = []) {
    const map = new Map();
    (pandoraData || []).forEach(item => {
      const key = pandoraDocKey(item) || (item.chaveNorm ? `CH_${item.chaveNorm}` : '') || pandoraChaveNorm(item.chave || '');
      if (key) map.set(key, item);
    });
    (rows || []).forEach(raw => {
      if (!raw) return;
      const item = pandoraCompleteNfSerieFromChave(raw);
      const key = pandoraDocKey(item) || (item.chaveNorm ? `CH_${item.chaveNorm}` : '') || pandoraChaveNorm(item.chave || '');
      if (!key) return;
      map.set(key, { ...(map.get(key) || {}), ...item });
    });
    pandoraData = Array.from(map.values()).sort((a, b) => (b.updatedAtMs || b.importedAtMs || b.createdAtMs || 0) - (a.updatedAtMs || a.importedAtMs || a.createdAtMs || 0));
    if ((pandoraData || []).length <= 1500) pandoraWriteJson(PANDORA_LOCAL_KEY, pandoraData);
    pandoraFillParceiroDatalist();
    if (activeTab === 'pandora') renderPandora();
  }

  function pandoraUpsertLocalItem(item = {}) {
    if (!item) return;
    const key = pandoraDocKey(item) || (item.chaveNorm ? `CH_${item.chaveNorm}` : '') || pandoraChaveNorm(item.chave || '');
    if (!key) return;
    const idx = (pandoraData || []).findIndex(x => (pandoraDocKey(x) || (x.chaveNorm ? `CH_${x.chaveNorm}` : '') || pandoraChaveNorm(x.chave || '')) === key);
    if (idx >= 0) pandoraData[idx] = { ...pandoraData[idx], ...item };
    else pandoraData.unshift(item);
    if ((pandoraData || []).length <= 1500) pandoraWriteJson(PANDORA_LOCAL_KEY, pandoraData);
    pandoraFillParceiroDatalist();
    if (activeTab === 'pandora') renderPandora();
  }

  async function pandoraGetByChaveFromFirestore(chaveNorm = '') {
    const key = pandoraChaveNorm(chaveNorm || '');
    if (!db || !key || pandoraUsingLocalFallback) return null;
    try {
      const item = await pandoraGetByDocIdFromFirestore(`CH_${key}`);
      if (!item) return null;
      pandoraUpsertLocalItem(item);
      return item;
    } catch (err) {
      console.warn('Pandora não conseguiu buscar a chave direto no Firebase:', err);
      return null;
    }
  }
  const pandoraDefaultArea = (item = {}) => item.area || 'Fiscal';
  const pandoraCentroKey = (value = '') => String(value ?? '').replace(/\D/g, '').replace(/^0+/, '') || String(value ?? '').trim();
  const pandoraClienteKey = (value = '') => {
    const digits = pandoraDigits(value).replace(/^0+/, '');
    return digits || pandoraSheetKey(value);
  };
  const pandoraNormalizeAreaCliente = (value = '') => String(value ?? '').trim();
  const pandoraAreaProtegidaPorCliente = (item = {}) => !!(item.areaClienteProtegida || item.areaOrigem === 'BASE_CLIENTES' || item.clienteArea);

  function pandoraClienteBaseMap() {
    const map = new Map();
    (pandoraClientesBase || []).forEach(row => {
      const key = row.codigoKey || pandoraClienteKey(row.codigo || row.clienteCodigo || '');
      if (key) map.set(key, row);
    });
    return map;
  }

  function pandoraParceiroMinimumLikeLength(key = '') {
    const value = String(key || '').trim();
    return pandoraDigits(value).length >= 4 || pandoraSheetKey(value).length >= 4;
  }

  function pandoraParceiroSimilarityScore(inputKey = '', candidateKey = '') {
    const input = String(inputKey || '').trim();
    const candidate = String(candidateKey || '').trim();
    if (!input || !candidate) return 0;
    if (input === candidate) return 1000 + Math.min(candidate.length, 30);
    if (!pandoraParceiroMinimumLikeLength(input)) return 0;

    const inputDigits = pandoraDigits(input);
    const candidateDigits = pandoraDigits(candidate);
    if (inputDigits && candidateDigits) {
      if (inputDigits === candidateDigits) return 1000 + Math.min(candidateDigits.length, 30);
      const maxLen = Math.min(inputDigits.length, candidateDigits.length, 10);
      for (let len = maxLen; len >= 4; len--) {
        if (inputDigits.slice(-len) === candidateDigits.slice(-len)) return 820 + len;
        if (inputDigits.slice(0, len) === candidateDigits.slice(0, len)) return 760 + len;
      }
      if (candidateDigits.includes(inputDigits) || inputDigits.includes(candidateDigits)) return 620 + Math.min(inputDigits.length, candidateDigits.length);
    }

    if (candidate.includes(input) || input.includes(candidate)) return 560 + Math.min(input.length, candidate.length);
    return 0;
  }

  function pandoraFindClienteBaseLike(value = '') {
    const inputKey = pandoraClienteKey(value);
    if (!inputKey) return null;
    const exact = pandoraClienteBaseMap().get(inputKey);
    if (exact) {
      return { row: exact, score: 1000, matchType: 'exato', source: 'BASE_CLIENTES', matchedCode: exact.codigo || value };
    }

    let best = null;
    (pandoraClientesBase || []).forEach(row => {
      const candidateKey = row.codigoKey || pandoraClienteKey(row.codigo || row.clienteCodigo || '');
      const score = pandoraParceiroSimilarityScore(inputKey, candidateKey);
      if (score >= 560 && (!best || score > best.score)) {
        best = { row, score, matchType: 'parecido', source: 'BASE_CLIENTES', matchedCode: row.codigo || row.clienteCodigo || '' };
      }
    });
    return best;
  }

  function pandoraFindExistingParceiroLike(value = '') {
    const inputKey = pandoraClienteKey(value);
    if (!inputKey) return null;
    let best = null;
    (pandoraVisibleRows(pandoraData || []) || []).forEach(row => {
      const candidateCode = row.parceiro || row.clienteCodigo || '';
      const candidateKey = row.clienteCodigoKey || pandoraClienteKey(candidateCode);
      const score = pandoraParceiroSimilarityScore(inputKey, candidateKey);
      if (score < 560) return;
      const hasUsefulInfo = !!(row.area || row.responsavel || row.fornecedor || row.clienteNomeBase || row.clienteArea || row.responsavelBase);
      if (!hasUsefulInfo) return;
      const recencyBonus = Math.min(Math.floor((row.updatedAtMs || row.importedAtMs || row.createdAtMs || 0) / 100000000000), 9);
      const finalScore = score + recencyBonus;
      if (!best || finalScore > best.score) {
        best = { row, score: finalScore, matchType: score >= 1000 ? 'exato' : 'parecido', source: 'HISTORICO_PANDORA', matchedCode: candidateCode };
      }
    });
    return best;
  }

  function pandoraResolveParceiroMatch(value = '') {
    const baseMatch = pandoraFindClienteBaseLike(value);
    const historyMatch = pandoraFindExistingParceiroLike(value);
    if (!baseMatch && !historyMatch) return null;

    const base = baseMatch?.row || {};
    const hist = historyMatch?.row || {};
    const primary = baseMatch || historyMatch;
    const codigo = base.codigo || hist.clienteCodigo || hist.parceiro || primary.matchedCode || value;
    const nome = base.nome || hist.clienteNomeBase || hist.fornecedor || '';
    const area = base.area || hist.clienteArea || hist.area || '';
    const responsavel = base.responsavel || hist.responsavel || hist.responsavelBase || '';
    const origem = [];
    if (baseMatch) origem.push('Base Clientes');
    if (historyMatch && (hist.responsavel || hist.area || hist.fornecedor)) origem.push('Histórico Pandora');

    return {
      codigo,
      codigoKey: pandoraClienteKey(codigo || value),
      nome,
      area,
      responsavel,
      matchType: primary.matchType || 'exato',
      score: Math.max(baseMatch?.score || 0, historyMatch?.score || 0),
      source: baseMatch ? 'BASE_CLIENTES' : 'HISTORICO_PANDORA',
      sourceLabel: origem.join(' + ') || (baseMatch ? 'Base Clientes' : 'Histórico Pandora'),
      hasBase: !!baseMatch,
      matchedCode: primary.matchedCode || codigo
    };
  }

  function pandoraSetParceiroHint(textValue = '', type = 'info') {
    const hint = document.getElementById('pd-parceiro-match-hint');
    if (!hint) return;
    hint.textContent = textValue || 'Digite o código para buscar na Base de Clientes e no histórico.';
    hint.className = type === 'ok'
      ? 'text-xs mt-1 font-semibold text-emerald-700'
      : (type === 'warn' ? 'text-xs mt-1 font-semibold text-amber-700' : 'pandora-muted text-xs mt-1');
  }

  function pandoraSetFieldIfAllowed(id, value = '', opts = {}) {
    const el = document.getElementById(id);
    const next = String(value || '').trim();
    if (!el || !next) return false;
    const current = String(el.value || '').trim();
    const isDefaultArea = id === 'pd-area' && pandoraNorm(current) === 'FISCAL';
    if (opts.force || !current || isDefaultArea) {
      el.value = next;
      try { el.dispatchEvent(new Event('change', { bubbles: true })); } catch (_) {}
      return true;
    }
    return false;
  }

  function pandoraApplyParceiroMatchToPayload(payload = {}) {
    const match = pandoraResolveParceiroMatch(payload.parceiro || payload.clienteCodigo || '');
    if (!match) return payload;
    return {
      ...payload,
      area: payload.area || match.area || '',
      fornecedor: payload.fornecedor || match.nome || '',
      responsavel: payload.responsavel || match.responsavel || '',
      clienteCodigo: match.codigo || payload.parceiro || '',
      clienteCodigoKey: match.codigoKey || pandoraClienteKey(match.codigo || payload.parceiro || ''),
      clienteNomeBase: match.nome || payload.fornecedor || '',
      clienteArea: match.area || payload.area || '',
      responsavelBase: match.responsavel || '',
      parceiroMatchOrigem: match.sourceLabel || '',
      parceiroMatchTipo: match.matchType || '',
      areaOrigem: match.hasBase && match.area ? 'BASE_CLIENTES' : (payload.areaOrigem || (match.area ? 'HISTORICO_PANDORA' : '')),
      areaClienteProtegida: !!(payload.areaClienteProtegida || (match.hasBase && match.area))
    };
  }

  function pandoraAutocompleteParceiro(opts = {}) {
    const parceiroEl = document.getElementById('pd-parceiro');
    if (!parceiroEl) return null;
    const raw = String(parceiroEl.value || '').trim();
    parceiroEl.classList.remove('pandora-lookup-ok', 'pandora-lookup-new');
    if (!raw) {
      pandoraSetParceiroHint('', 'info');
      return null;
    }

    const match = pandoraResolveParceiroMatch(raw);
    if (!match) {
      if (pandoraParceiroMinimumLikeLength(pandoraClienteKey(raw))) parceiroEl.classList.add('pandora-lookup-new');
      pandoraSetParceiroHint('Nenhum parceiro parecido encontrado na Base de Clientes ou no histórico.', 'warn');
      if (opts.showToast) showToast('Nenhum parceiro parecido encontrado para esse código.', 'info');
      return null;
    }

    if (opts.autocorrect && match.codigo && match.matchType !== 'exato') parceiroEl.value = match.codigo;
    pandoraSetFieldIfAllowed('pd-area', match.area, { force: opts.forceArea });
    pandoraSetFieldIfAllowed('pd-fornecedor', match.nome, { force: false });
    pandoraSetFieldIfAllowed('pd-responsavel', match.responsavel, { force: false });
    parceiroEl.classList.add('pandora-lookup-ok');

    const partes = [];
    if (match.nome) partes.push(match.nome);
    if (match.area) partes.push(`Área: ${match.area}`);
    if (match.responsavel) partes.push(`Responsável: ${match.responsavel}`);
    pandoraSetParceiroHint(`Parceiro ${match.matchType === 'exato' ? 'encontrado' : 'parecido encontrado'} em ${match.sourceLabel}: ${partes.join(' • ') || match.codigo}`, 'ok');
    if (opts.showToast) showToast(`Parceiro ${match.matchType === 'exato' ? 'encontrado' : 'parecido encontrado'}: ${partes.join(' • ') || match.codigo}`, 'success');
    return match;
  }

  function pandoraFillParceiroDatalist() {
    const listEl = document.getElementById('pd-parceiro-list');
    if (!listEl) return;
    const options = new Map();
    (pandoraClientesBase || []).forEach(row => {
      const codigo = String(row.codigo || row.clienteCodigo || '').trim();
      if (!codigo) return;
      const label = [row.nome, row.area ? `Área: ${row.area}` : '', row.responsavel ? `Resp.: ${row.responsavel}` : ''].filter(Boolean).join(' • ');
      options.set(codigo, label);
    });
    (pandoraVisibleRows(pandoraData || []) || []).slice(0, 500).forEach(row => {
      const codigo = String(row.parceiro || row.clienteCodigo || '').trim();
      if (!codigo || options.has(codigo)) return;
      const label = [row.fornecedor || row.clienteNomeBase, row.area ? `Área: ${row.area}` : '', row.responsavel ? `Resp.: ${row.responsavel}` : ''].filter(Boolean).join(' • ');
      options.set(codigo, label);
    });
    listEl.innerHTML = Array.from(options.entries()).slice(0, 800).map(([value, label]) => `<option value="${escapeHtml(value)}" label="${escapeHtml(label)}"></option>`).join('');
  }

  function pandoraAreaOptions() {
    const set = new Set(PANDORA_AREAS.filter(Boolean));
    (pandoraData || []).forEach(item => {
      if (item.area) set.add(item.area);
      if (item.clienteArea) set.add(item.clienteArea);
    });
    (pandoraClientesBase || []).forEach(item => { if (item.area) set.add(item.area); });
    return Array.from(set).filter(Boolean).sort((a, b) => a.localeCompare(b, 'pt-BR'));
  }

  function pandoraApplyClienteBaseToXmlRow(row = {}, existing = {}) {
    const parceiroRef = row.parceiro || existing.parceiro || existing.clienteCodigo || row.clienteCodigo || '';
    const exactBase = pandoraClienteBaseMap().get(pandoraClienteKey(parceiroRef));
    const likeBase = exactBase ? { row: exactBase, score: 1000, matchType: 'exato', source: 'BASE_CLIENTES' } : pandoraFindClienteBaseLike(parceiroRef);
    const base = likeBase && likeBase.score >= 820 ? likeBase.row : null;
    if (!base || !base.area) return row;
    return {
      ...row,
      area: base.area,
      fornecedor: row.fornecedor || existing.fornecedor || base.nome || '',
      responsavel: existing.responsavel || row.responsavel || base.responsavel || '',
      responsavelBase: base.responsavel || existing.responsavelBase || '',
      clienteCodigo: base.codigo || row.parceiro || existing.parceiro || '',
      clienteCodigoKey: base.codigoKey || pandoraClienteKey(base.codigo || row.parceiro || ''),
      clienteNomeBase: base.nome || '',
      clienteArea: base.area || '',
      areaOrigem: 'BASE_CLIENTES',
      areaClienteProtegida: true,
      parceiroMatchOrigem: 'Base Clientes',
      parceiroMatchTipo: likeBase.matchType || 'exato',
      clienteBaseArquivo: base.arquivoOrigem || '',
      clienteBaseUploadRow: base.uploadRow || '',
      clienteBaseImportedAt: base.importedAt || ''
    };
  }

  function pandoraMergeXmlRow(existing, row) {
    const rowComCliente = pandoraApplyClienteBaseToXmlRow(row, existing || {});
    const rowCompleta = pandoraCompleteNfSerieFromChave(rowComCliente);
    if (!existing) return rowCompleta;
    const existingCompleto = pandoraCompleteNfSerieFromChave(existing);
    const protegido = pandoraAreaProtegidaPorCliente(existingCompleto) || pandoraAreaProtegidaPorCliente(rowCompleta);
    const merged = {
      ...existingCompleto,
      ...rowCompleta,
      nf: rowCompleta.nf || existingCompleto.nf || '',
      serie: rowCompleta.serie || existingCompleto.serie || '',
      status: existingCompleto.status || rowCompleta.status,
      responsavel: existingCompleto.responsavel || rowCompleta.responsavel,
      tratativa: existingCompleto.tratativa || rowCompleta.tratativa,
      observacao: existingCompleto.observacao || rowCompleta.observacao,
      problema: existingCompleto.problema || rowCompleta.problema,
      _docId: existingCompleto._docId || rowCompleta._docId,
      id: existingCompleto.id || rowCompleta.id
    };
    if (protegido) {
      merged.area = rowCompleta.area || existingCompleto.area || 'Fiscal';
      merged.areaOrigem = 'BASE_CLIENTES';
      merged.areaClienteProtegida = true;
      merged.clienteCodigo = rowCompleta.clienteCodigo || existingCompleto.clienteCodigo || existingCompleto.parceiro || rowCompleta.parceiro || '';
      merged.clienteCodigoKey = rowCompleta.clienteCodigoKey || existingCompleto.clienteCodigoKey || pandoraClienteKey(merged.clienteCodigo);
      merged.clienteNomeBase = rowCompleta.clienteNomeBase || existingCompleto.clienteNomeBase || '';
      merged.clienteArea = rowCompleta.clienteArea || existingCompleto.clienteArea || merged.area;
      merged.clienteBaseArquivo = rowCompleta.clienteBaseArquivo || existingCompleto.clienteBaseArquivo || '';
      merged.clienteBaseUploadRow = rowCompleta.clienteBaseUploadRow || existingCompleto.clienteBaseUploadRow || '';
      merged.clienteBaseImportedAt = rowCompleta.clienteBaseImportedAt || existingCompleto.clienteBaseImportedAt || '';
    }
    return pandoraCompleteNfSerieFromChave(merged);
  }

  function pandoraRefreshAreaControls() {
    const areas = pandoraAreaOptions();
    pandoraFillSelect('pd-area', areas);
    pandoraFillSelect('pandora-filter-area', areas, { allLabel: 'Todas as áreas' });
  }

  function pandoraIsJacarei(item = {}) {
    const site = pandoraNorm(item.sitePandora || item.site || item.unidade || item.filial || '');
    if (site.includes('JACAREI')) return true;
    const centro = pandoraCentroKey(item.centro || '');
    const centrosJacarei = PANDORA_JACAREI_CENTROS.map(pandoraCentroKey);
    return !!centro && centrosJacarei.includes(centro);
  }

  function pandoraVisibleRows(rows = pandoraData || []) {
    return (rows || []).map(pandoraCompleteNfSerieFromChave).filter(pandoraIsJacarei);
  }

  function pandoraIsOldPendingVisible(item = {}) {
    const completed = pandoraCompleteNfSerieFromChave(item || {});
    if (!pandoraIsJacarei(completed)) return false;
    if (!pandoraIsPendente(completed)) return false;
    const aging = pandoraAgingInfo(completed);
    return aging && aging.days !== null && aging.days > PANDORA_VISIBLE_MIN_AGE_DAYS;
  }

  function pandoraOldPendingVisibleRows(rows = pandoraData || []) {
    return (rows || []).map(pandoraCompleteNfSerieFromChave).filter(pandoraIsOldPendingVisible);
  }

  function pandoraOldPendingLabel() {
    return `Exibição automática: NFs pendentes acima de ${PANDORA_VISIBLE_MIN_AGE_DAYS} dias. Demais NFs somente pela chave de acesso.`;
  }

  function pandoraDateFilterLabel() {
    if (!pandoraDateFilter?.active) return pandoraOldPendingLabel();
    const start = pandoraDateFilter.startDate ? pandoraDateFilter.startDate.split('-').reverse().join('/') : 'início';
    const end = pandoraDateFilter.endDate ? pandoraDateFilter.endDate.split('-').reverse().join('/') : 'fim';
    return `Filtro de emissão ativo: ${start} até ${end}. Mostrando NFs pendentes do período carregado.`;
  }

  function pandoraInputDateStartMs(value = '') {
    const m = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return 0;
    const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]), 0, 0, 0, 0);
    return Number.isNaN(d.getTime()) ? 0 : d.getTime();
  }

  function pandoraInputDateEndMs(value = '') {
    const start = pandoraInputDateStartMs(value);
    return start ? start + 86399999 : 0;
  }

  function pandoraSetDateInputs(startDate = '', endDate = '') {
    ['pandora-date-start', 'pandora-db-date-start'].forEach(id => { const el = document.getElementById(id); if (el) el.value = startDate || ''; });
    ['pandora-date-end', 'pandora-db-date-end'].forEach(id => { const el = document.getElementById(id); if (el) el.value = endDate || ''; });
  }

  function pandoraCurrentListRows(rows = pandoraData || []) {
    const base = (rows || [])
      .map(pandoraCompleteNfSerieFromChave)
      .filter(pandoraIsJacarei)
      .filter(pandoraIsPendente);

    if (pandoraDateFilter?.active) {
      const startMs = Number(pandoraDateFilter.startMs || 0);
      const endMs = Number(pandoraDateFilter.endMs || 0);
      return base.filter(item => {
        const emissaoMs = Number(item.emissaoMs || 0) || pandoraDateStartMs(item.dataEmissaoXml || item.dataEmissao || item.emissao || '');
        return !!emissaoMs && (!startMs || emissaoMs >= startMs) && (!endMs || emissaoMs <= endMs);
      });
    }

    return base.filter(pandoraIsOldPendingVisible);
  }

  async function pandoraLoadDateRangeFromFirestore(startMs = 0, endMs = 0) {
    if (!startMs || !endMs) return [];
    if (!db || pandoraUsingLocalFallback) return pandoraCurrentListRows();

    const allRows = [];
    // Busca por período somente nas coleções que podem conter operação pendente.
    // O arquivo de Escriturado continua consultável pela chave de acesso.
    const dateCollections = [PANDORA_ACTIVE_COLLECTION, PANDORA_NF_COLLECTION];
    for (const collectionName of dateCollections) {
      try {
        const snap = await getDocs(query(
          pandoraCollection(collectionName),
          where('emissaoMs', '>=', startMs),
          where('emissaoMs', '<=', endMs),
          orderBy('emissaoMs', 'desc'),
          limit(PANDORA_DATE_FILTER_LIMIT)
        ));
        snap.docs.forEach(d => allRows.push(pandoraWithSource({ ...d.data(), id: d.id, _docId: d.id }, collectionName)));
      } catch (err) {
        console.warn(`Pandora não conseguiu buscar por data na coleção ${collectionName}:`, err);
      }
    }

    const rows = pandoraDedupRows(allRows);
    pandoraMergeLoadedRows(rows);
    updatePandoraImportSummary();
    return rows;
  }

  async function pandoraApplyDateFilter(source = 'painel') {
    const startId = source === 'banco' ? 'pandora-db-date-start' : 'pandora-date-start';
    const endId = source === 'banco' ? 'pandora-db-date-end' : 'pandora-date-end';
    const startDate = document.getElementById(startId)?.value || '';
    const endDate = document.getElementById(endId)?.value || startDate;
    const startMs = pandoraInputDateStartMs(startDate);
    const endMs = pandoraInputDateEndMs(endDate);

    if (!startMs || !endMs) {
      showToast('Informe a data inicial e final para buscar as NFs do período.', 'info');
      return;
    }
    if (startMs > endMs) {
      showToast('A data inicial não pode ser maior que a data final.', 'error');
      return;
    }

    pandoraDateFilter = { active: true, startDate, endDate, startMs, endMs };
    pandoraSetDateInputs(startDate, endDate);
    resetPandoraPagination('painel');
    resetPandoraPagination('banco');

    try {
      showToast('Buscando NFs do período selecionado...', 'info');
      const loaded = await pandoraLoadDateRangeFromFirestore(startMs, endMs);
      renderPandora();
      showToast(`${loaded.length.toLocaleString('pt-BR')} NF${loaded.length === 1 ? '' : 's'} carregada${loaded.length === 1 ? '' : 's'} no período.`, 'success');
    } catch (err) {
      console.error('Erro ao filtrar Pandora por data:', err);
      renderPandora();
      showToast('Não foi possível carregar o período selecionado.', 'error');
    }
  }

  function pandoraClearDateFilter() {
    pandoraDateFilter = { active: false, startDate: '', endDate: '', startMs: 0, endMs: 0 };
    pandoraSetDateInputs('', '');
    resetPandoraPagination('painel');
    resetPandoraPagination('banco');
    renderPandora();
    showToast('Filtro de data removido. Voltou para NFs pendentes acima de 30 dias.', 'success');
  }

  function pandoraJacareiLabel() {
    return `Filtro ativo: ${PANDORA_SITE_ATIVO} (${PANDORA_JACAREI_CENTROS.join(' / ')})`;
  }

  function pandoraSummaryRef() {
    return pandoraDocRef(PANDORA_DASHBOARD_SUMMARY_COLLECTION, PANDORA_DASHBOARD_SUMMARY_DOC);
  }

  function pandoraEmptyDashboardSummary(source = 'Vazio') {
    return {
      site: PANDORA_SITE_ATIVO,
      centros: [...PANDORA_JACAREI_CENTROS],
      totalNfs: 0,
      valorPendenteTotal: 0,
      statusCounts: {},
      areaStats: {},
      agingStats: {},
      source,
      updatedAt: '',
      updatedAtMs: 0
    };
  }

  function pandoraNormalizeDashboardSummary(raw = {}) {
    return {
      ...pandoraEmptyDashboardSummary(raw.source || 'Resumo'),
      ...(raw || {}),
      totalNfs: Math.max(0, Number(raw.totalNfs || 0)),
      valorPendenteTotal: Math.max(0, Number(raw.valorPendenteTotal || 0)),
      statusCounts: raw.statusCounts && typeof raw.statusCounts === 'object' ? raw.statusCounts : {},
      areaStats: raw.areaStats && typeof raw.areaStats === 'object' ? raw.areaStats : {},
      agingStats: raw.agingStats && typeof raw.agingStats === 'object' ? raw.agingStats : {}
    };
  }

  function pandoraSummaryCleanNumber(value = 0) {
    const num = Number(value || 0);
    return Number.isFinite(num) ? Math.max(0, Math.round(num * 100) / 100) : 0;
  }

  function pandoraSummaryAgingBucket(item = {}) {
    const aging = pandoraAgingInfo(item);
    if (!aging || aging.days === null || aging.days < 30) return '';
    if (aging.days >= 90) return 'd90';
    if (aging.days >= 60) return 'd60';
    return 'd30';
  }

  function pandoraSummaryItemMetrics(item = {}) {
    const completed = pandoraCompleteNfSerieFromChave(item || {});
    if (!pandoraIsJacarei(completed)) return null;
    const status = pandoraDefaultStatus(completed) || 'Em andamento';
    const area = pandoraDefaultArea(completed) || 'Não informado';
    const pending = pandoraIsPendente(completed);
    return {
      status,
      area,
      pending,
      valorPendente: pending ? pandoraParseMoney(completed.valorNf) : 0,
      agingBucket: pending ? pandoraSummaryAgingBucket(completed) : ''
    };
  }

  function pandoraApplyItemToSummary(summaryInput = {}, item = {}, direction = 1) {
    const metrics = pandoraSummaryItemMetrics(item);
    const summary = pandoraNormalizeDashboardSummary(summaryInput);
    if (!metrics) return summary;
    const dir = direction >= 0 ? 1 : -1;

    summary.totalNfs = Math.max(0, Number(summary.totalNfs || 0) + dir);
    summary.statusCounts[metrics.status] = Math.max(0, Number(summary.statusCounts[metrics.status] || 0) + dir);
    if (summary.statusCounts[metrics.status] === 0) delete summary.statusCounts[metrics.status];

    if (!summary.areaStats[metrics.area]) summary.areaStats[metrics.area] = { total: 0, pendente: 0, valorPendente: 0 };
    const areaInfo = summary.areaStats[metrics.area];
    areaInfo.total = Math.max(0, Number(areaInfo.total || 0) + dir);
    if (metrics.pending) {
      areaInfo.pendente = Math.max(0, Number(areaInfo.pendente || 0) + dir);
      areaInfo.valorPendente = pandoraSummaryCleanNumber(Number(areaInfo.valorPendente || 0) + (dir * Number(metrics.valorPendente || 0)));
      summary.valorPendenteTotal = pandoraSummaryCleanNumber(Number(summary.valorPendenteTotal || 0) + (dir * Number(metrics.valorPendente || 0)));
    }
    if (areaInfo.total === 0 && areaInfo.pendente === 0) delete summary.areaStats[metrics.area];

    if (metrics.pending && metrics.agingBucket) {
      if (!summary.agingStats[metrics.area]) summary.agingStats[metrics.area] = { d30: 0, d60: 0, d90: 0, total: 0 };
      const agingInfo = summary.agingStats[metrics.area];
      agingInfo[metrics.agingBucket] = Math.max(0, Number(agingInfo[metrics.agingBucket] || 0) + dir);
      agingInfo.total = Math.max(0, Number(agingInfo.total || 0) + dir);
      if (agingInfo.total === 0) delete summary.agingStats[metrics.area];
    }

    return summary;
  }

  function pandoraBuildDashboardSummaryFromRows(rows = [], source = 'Reconstrução') {
    let summary = pandoraEmptyDashboardSummary(source);
    (rows || []).forEach(item => { summary = pandoraApplyItemToSummary(summary, item, 1); });
    summary.updatedAt = pandoraNow();
    summary.updatedAtMs = pandoraMs();
    return pandoraNormalizeDashboardSummary(summary);
  }

  async function pandoraSaveDashboardSummary(summaryInput = {}, source = 'Atualização') {
    const summary = pandoraNormalizeDashboardSummary({ ...summaryInput, source, updatedAt: pandoraNow(), updatedAtMs: pandoraMs() });
    pandoraDashboardSummary = summary;
    if (db && !pandoraUsingLocalFallback) {
      await setDoc(pandoraSummaryRef(), summary, { merge: false });
    }
    if (activeTab === 'pandora' && pandoraLastView === 'dashboard') renderPandoraDashboard();
    return summary;
  }

  async function pandoraAdjustDashboardSummaryDelta(beforeItem = null, afterItem = null, source = 'Alteração de NF') {
    if (!db || pandoraUsingLocalFallback) return;
    try {
      let summary = pandoraDashboardSummary;
      if (!summary) {
        const snap = await getDoc(pandoraSummaryRef());
        if (!snap.exists()) return;
        summary = pandoraNormalizeDashboardSummary(snap.data());
      }
      if (beforeItem) summary = pandoraApplyItemToSummary(summary, beforeItem, -1);
      if (afterItem) summary = pandoraApplyItemToSummary(summary, afterItem, 1);
      await pandoraSaveDashboardSummary(summary, source);
    } catch (err) {
      console.warn('Pandora não conseguiu atualizar o resumo do dashboard:', err);
    }
  }

  async function rebuildPandoraDashboardSummary() {
    if (!db || pandoraUsingLocalFallback) {
      await pandoraSaveDashboardSummary(pandoraBuildDashboardSummaryFromRows(pandoraVisibleRows(), 'Cache local'), 'Cache local');
      showToast('Resumo Pandora atualizado com os dados carregados no navegador.', 'success');
      return;
    }
    if (pandoraDashboardSummaryLoading) return;
    pandoraDashboardSummaryLoading = true;
    const btn = document.getElementById('pandora-rebuild-summary-btn');
    const statusEl = document.getElementById('pandora-summary-status');
    try {
      if (btn) { btn.disabled = true; btn.textContent = 'Atualizando...'; }
      if (statusEl) statusEl.textContent = 'Lendo o Banco XML uma vez para reconstruir o resumo consolidado do Pandora.';
      showToast('Atualizando resumo do Pandora. Essa leitura completa acontece apenas quando você solicita.', 'info');
      const rows = await pandoraGetAllOperationalRowsFromFirestore();
      const summary = pandoraBuildDashboardSummaryFromRows(rows, 'Reconstrução manual');
      await pandoraSaveDashboardSummary(summary, 'Reconstrução manual');
      showToast(`Resumo Pandora atualizado: ${Number(summary.totalNfs || 0).toLocaleString('pt-BR')} NFs consolidadas.`, 'success');
    } catch (err) {
      console.error('Erro ao atualizar resumo do Pandora:', err);
      showToast('Não foi possível atualizar o resumo do Pandora.', 'error');
    } finally {
      pandoraDashboardSummaryLoading = false;
      if (btn) { btn.disabled = false; btn.textContent = 'Atualizar resumo'; }
    }
  }

  function renderPandoraDashboardSummary(summaryInput = {}) {
    const summary = pandoraNormalizeDashboardSummary(summaryInput);
    const statusCounts = summary.statusCounts || {};
    const andamento = (statusCounts['Em andamento'] || 0) + (statusCounts['Aguardando área'] || 0) + (statusCounts['Aguardando documento'] || 0);

    pandoraSetText('pd-kpi-total', Number(summary.totalNfs || 0).toLocaleString('pt-BR'));
    pandoraSetText('pd-kpi-andamento', Number(andamento || 0).toLocaleString('pt-BR'));
    pandoraSetText('pd-kpi-escriturada', Number(statusCounts['Escriturado'] || 0).toLocaleString('pt-BR'));
    pandoraSetText('pd-kpi-problema', pandoraFormatMoney(summary.valorPendenteTotal || 0));

    const statusEl = document.getElementById('pandora-summary-status');
    if (statusEl) {
      const when = summary.updatedAtMs ? new Date(summary.updatedAtMs).toLocaleString('pt-BR') : 'ainda não atualizado';
      statusEl.textContent = `Resumo consolidado de ${PANDORA_SITE_ATIVO}. Última atualização: ${when}. Detalhes de NF são consultados pela chave de acesso.`;
    }

    const areaList = document.getElementById('pandora-area-list');
    if (areaList) {
      const entries = Object.entries(summary.areaStats || {}).sort((a,b) => (Number(b[1].pendente || 0) - Number(a[1].pendente || 0)) || (Number(b[1].total || 0) - Number(a[1].total || 0)));
      const max = Math.max(1, ...entries.map(([,v]) => Number(v.total || 0)));
      areaList.innerHTML = entries.length ? entries.map(([area, info]) => `
        <div class="pandora-area-row" style="grid-template-columns:minmax(150px,1.2fr) minmax(160px,2fr) minmax(110px,.8fr);">
          <div class="font-bold" title="${escapeHtml(area)}">${escapeHtml(area)}</div>
          <div>
            <div class="pandora-area-bar"><span style="width:${Math.max(6, (Number(info.total || 0) / max) * 100)}%"></span></div>
            <div class="text-xs pandora-muted mt-1">Pendentes: <b>${Number(info.pendente || 0).toLocaleString('pt-BR')}</b> • Valor pendente: <b>${escapeHtml(pandoraFormatMoney(info.valorPendente || 0))}</b></div>
          </div>
          <div class="font-black text-right">${Number(info.pendente || 0).toLocaleString('pt-BR')}/${Number(info.total || 0).toLocaleString('pt-BR')}</div>
        </div>
      `).join('') : '<div class="pandora-muted">Resumo ainda não gerado. Clique em Atualizar resumo.</div>';
    }

    const agingAreaBody = document.getElementById('pandora-aging-area-body');
    if (agingAreaBody) {
      const agingEntries = Object.entries(summary.agingStats || {}).sort((a,b) =>
        (Number(b[1].total || 0) - Number(a[1].total || 0)) || (Number(b[1].d90 || 0) - Number(a[1].d90 || 0)) || (Number(b[1].d60 || 0) - Number(a[1].d60 || 0)) || a[0].localeCompare(b[0], 'pt-BR')
      );
      if (!agingEntries.length) {
        agingAreaBody.innerHTML = '<tr><td colspan="5" class="text-center pandora-muted py-6">Nenhuma NF pendente acima de 30 dias no resumo.</td></tr>';
      } else {
        const totals = agingEntries.reduce((acc, [, info]) => {
          acc.d30 += Number(info.d30 || 0); acc.d60 += Number(info.d60 || 0); acc.d90 += Number(info.d90 || 0); acc.total += Number(info.total || 0);
          return acc;
        }, { d30: 0, d60: 0, d90: 0, total: 0 });
        agingAreaBody.innerHTML = agingEntries.map(([area, info]) => `
          <tr>
            <td class="font-bold">${escapeHtml(area)}</td>
            <td class="text-center"><span class="pandora-aging-count pandora-aging-30">${Number(info.d30 || 0).toLocaleString('pt-BR')}</span></td>
            <td class="text-center"><span class="pandora-aging-count pandora-aging-60">${Number(info.d60 || 0).toLocaleString('pt-BR')}</span></td>
            <td class="text-center"><span class="pandora-aging-count pandora-aging-90">${Number(info.d90 || 0).toLocaleString('pt-BR')}</span></td>
            <td class="text-center font-black">${Number(info.total || 0).toLocaleString('pt-BR')}</td>
          </tr>
        `).join('') + `
          <tr class="pandora-aging-total-row">
            <td>Total geral</td>
            <td class="text-center">${totals.d30.toLocaleString('pt-BR')}</td>
            <td class="text-center">${totals.d60.toLocaleString('pt-BR')}</td>
            <td class="text-center">${totals.d90.toLocaleString('pt-BR')}</td>
            <td class="text-center">${totals.total.toLocaleString('pt-BR')}</td>
          </tr>`;
      }
    }

    const canvas = document.getElementById('pandora-status-chart');
    if (canvas && typeof Chart !== 'undefined') {
      const labels = PANDORA_STATUS;
      const data = labels.map(label => Number(statusCounts[label] || 0));
      if (pandoraStatusChart) pandoraStatusChart.destroy();
      pandoraStatusChart = new Chart(canvas, {
        type: 'doughnut',
        data: { labels, datasets: [{ data }] },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { position: 'bottom' } }
        }
      });
    }
  }

  function pandoraSetImportStatus(textValue, type = 'info') {
    const el = document.getElementById('pandora-import-status');
    if (!el) return;
    el.textContent = textValue || 'Banco XML: aguardando upload';
    el.style.background = type === 'error' ? 'rgba(220,38,38,.22)' : (type === 'success' ? 'rgba(22,163,74,.22)' : 'rgba(255,255,255,.12)');
  }

  function pandoraExcelDate(value) {
    if (value == null || value === '') return '';
    if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toLocaleDateString('pt-BR');
    if (typeof value === 'number' && Number.isFinite(value)) {
      const ms = Math.round((value - 25569) * 86400 * 1000);
      const d = new Date(ms);
      return Number.isNaN(d.getTime()) ? String(value) : d.toLocaleDateString('pt-BR', { timeZone: 'UTC' });
    }
    return String(value ?? '').trim();
  }

  function pandoraValueByHeader(row = {}, aliases = []) {
    const map = {};
    Object.keys(row || {}).forEach(k => { map[pandoraSheetKey(k)] = row[k]; });
    for (const alias of aliases) {
      const key = pandoraSheetKey(alias);
      if (Object.prototype.hasOwnProperty.call(map, key)) return map[key];
    }
    return '';
  }

  function pandoraNormalizeUploadedRow(row = {}, idx = 0, fileName = '') {
    const chave = String(pandoraValueByHeader(row, ['CHAVE', 'Chave de acesso', 'Chave de Acesso', 'Chave acesso', 'Chave NF-e', 'Chave NFe', 'Chave']) || '').trim();
    const nf = String(pandoraValueByHeader(row, [
      'NOTA FISCAL',
      'Nota Fiscal',
      'Nº Nota Fiscal',
      'N° Nota Fiscal',
      'N Nota Fiscal',
      'Número Nota Fiscal',
      'Numero Nota Fiscal',
      'Número da NF',
      'Numero da NF',
      'Número NF',
      'Numero NF',
      'NF-e',
      'NFe',
      'NF'
    ]) || '').trim();
    const serie = String(pandoraValueByHeader(row, ['Serie', 'Série']) || '').trim();
    const dadosChave = pandoraExtractNfeFromChave(chave);
    const nfExtraida = nf || dadosChave.nf || '';
    const serieExtraida = serie || dadosChave.serie || '';
    const statusXml = String(pandoraValueByHeader(row, ['Status', 'Status XML']) || '').trim();
    const dataEmissaoXml = pandoraExcelDate(pandoraValueByHeader(row, ['Data Emissão XML', 'Data Emissao XML']));
    const dataEntradaXml = pandoraExcelDate(pandoraValueByHeader(row, ['Data Entrada XML']));
    const centro = String(pandoraValueByHeader(row, ['Centro']) || '').trim();
    const parceiro = String(pandoraValueByHeader(row, ['Parceiro']) || '').trim();
    const fornecedor = String(pandoraValueByHeader(row, ['Nome do Parceiro', 'Fornecedor / Cliente', 'Fornecedor']) || '').trim();
    const cnpjParceiro = String(pandoraValueByHeader(row, ['CNPJ Parceiro', 'CNPJ']) || '').trim();
    const cfop = String(pandoraValueByHeader(row, ['CFOP']) || '').trim();
    const valorNf = String(pandoraValueByHeader(row, ['XML Valor NF', 'Valor NF', 'Valor Total']) || '').trim();
    const processo = String(pandoraValueByHeader(row, ['Processo']) || '').trim();
    const descricaoProcesso = String(pandoraValueByHeader(row, ['Descrição do Processo', 'Descricao do Processo']) || '').trim();
    const processoEntrada = String(pandoraValueByHeader(row, ['Processo de Entrada']) || '').trim();
    const evento = String(pandoraValueByHeader(row, ['Evento']) || '').trim();
    const descricaoEvento = String(pandoraValueByHeader(row, ['Descrição do Evento', 'Descricao do Evento']) || '').trim();
    const docSubsequente = String(pandoraValueByHeader(row, ['Doc.Subsequente', 'Doc Subsequente']) || '').trim();
    const normalizedChave = pandoraChaveNorm(chave);
    const docId = normalizedChave ? `CH_${normalizedChave}` : pandoraLocalId('PDNF');
    return {
      id: docId,
      _docId: docId,
      nf: nfExtraida, serie: serieExtraida, chave, chaveNorm: normalizedChave,
      area: 'Fiscal',
      tipo: processoEntrada || descricaoProcesso || processo || 'Recebimento XML',
      statusXml,
      dataEmissaoXml,
      dataEntradaXml,
      emissaoMs: pandoraDateStartMs(dataEmissaoXml),
      emissaoDiaRef: dataEmissaoXml ? isoDate(pandoraDateStartMs(dataEmissaoXml)) : '',
      emissaoMesRef: dataEmissaoXml ? isoDate(pandoraDateStartMs(dataEmissaoXml)).slice(0, 7) : '',
      entradaMs: pandoraDateStartMs(dataEntradaXml),
      entradaDiaRef: dataEntradaXml ? isoDate(pandoraDateStartMs(dataEntradaXml)) : '',
      entradaMesRef: dataEntradaXml ? isoDate(pandoraDateStartMs(dataEntradaXml)).slice(0, 7) : '',
      centro,
      parceiro,
      fornecedor,
      cnpjParceiro,
      cfop,
      valorNf,
      processo,
      descricaoProcesso,
      processoEntrada,
      evento,
      descricaoEvento,
      docSubsequente,
      sitePandora: pandoraIsJacarei({ centro }) ? PANDORA_SITE_ATIVO : 'Outro',
      origemPandora: 'UPLOAD_XML',
      arquivoOrigem: fileName || '',
      uploadRow: idx + 2,
      importedAt: pandoraNow(),
      importedAtMs: pandoraMs()
    };
  }

  function pandoraHasJ1B3N(value = '') {
    return pandoraDigits(value).length > 0;
  }

